\cite[Theorem 1.1]{HMM2021}\label{thm:NormalSolutionHMM}
    Let $u$ solve \eqref{eq:euclidean}. Then
    \begin{equation*}
        u(x)=\frac{2}{|\mathbb S^n|}\int_{\mathbb R^n}\log\left(\frac{1+|y|}{|x-y|}\right)|y|^{n\gamma}e^{nu(y)}\,\mathrm d y+p(x),
    \end{equation*}
    where $p$ is a polynomial bounded above and of degree at most $n-1$. Moreover, 
    \begin{equation*}
        \lim_{|x|\to\infty}\frac{u(x)-p(x)}{|\log |x||}=-\frac{2\Lambda}{|\mathbb{S}^n|}.
    \end{equation*}
    If $p$ is constant, then
    \begin{equation}\label{eq:normal-mass-intro}
 \Lambda=\int_{\mathbb R^n}|x|^{n\gamma}e^{nu}\,\mathrm d x
 =\alpha|\mathbb S^n|.
\end{equation}

\label{thm:kelvin}
	Let $u$	be a normal solution of \eqref{eq:euclidean}. Then there is a unique $R>0$ such that
		\begin{equation}\label{u kelvin}
	u(x)=u\!\left(\frac{R^2x}{|x|^2}\right)				-2\alpha\log\frac{|x|}{R},			\qquad x\neq 0.
		\end{equation}
      Here $R$ is the unique radius such that
		\begin{equation}\label{R half mass}
			\int_{B_R}|x|^{n\gamma}e^{nu(x)}\,\mathrm d x=\frac{1}{2}\alpha|\mathbb S^n|.
		\end{equation}
		Equivalently, for $t_0=\log R$ and $V$ given by \eqref{EF trans}, we have
		\begin{equation}\label{V sym}
				V(t_0+t,\omega)=V(t_0-t,\omega),\qquad (t,\omega)\in\mathcal{C}.
		\end{equation}

\label{thm radial}
 For every $\alpha>0$, \eqref{eq:euclidean} has a unique radial normal solution up to dilation. Up to a  translation in $t$, the corresponding solution $v_\alpha$ of \eqref{eq:radial-equation} is even, strictly concave and strictly decreasing on $(0,\infty)$. Moreover, if $L_{\alpha,0}\phi=0$ for some bounded function $\phi$, then
$\phi\in\operatorname{span}\{v_\alpha'\}$.

\label{thm e value L}
 For every integer $k\ge2$, there is exactly one parameter $\alpha_{n,k}>1$ such that the kernel of $L_{\alpha_{n,k},k}$ is nontrivial. At this parameter, zero is the principal eigenvalue of $L_{\alpha_{n,k},k}$.  If $k_1\ne k_2$, then $\alpha_{n,k_1}\ne\alpha_{n,k_2}$.  Moreover,
 \begin{equation}\label{eq:main-range-intro}
  \mathfrak a_{n,k}<\alpha_{n,k}<\mathfrak a_{n,k}+\mathfrak b_{n,k},
 \end{equation}
 where
 \begin{equation}\label{def ak bk}
  \mathfrak a_{n,k}:=\frac{\Gamma(n+k-1)}{n\Gamma(k)\Gamma(n-1)},  \qquad  \mathfrak b_{n,k}:=\frac{k(n+k-2)}{n(n-2)}.
 \end{equation}

\label{al n2 nonint}
 For $k=2$, the estimate becomes
 \begin{equation*}
  n-1<\alpha_{n,2}<n-1+\frac{2}{n-2}.
 \end{equation*}
 Thus $\alpha_{n,2}$ is not an integer whenever $n\ge4$.

\label{coro:nondegen}
Let $0<\alpha<\alpha_{n,2}$. Then the solution $v_\alpha$ given in Theorem~\ref{thm radial} is nondegenerate in the following sense: 
let $h$ be a bounded distributional solution of $L_\alpha h=0$ on $\mathcal C$. If $\alpha\neq 1$, then $h\in \operatorname{span}\{v_\alpha'\}$. If $\alpha=1$, then
\begin{equation}\label{h kernel}
    h(t,\omega)=-c_0\tanh{t}+\operatorname{sech} t\sum_{i=1}^nc_i\omega_i
    \end{equation}
    for some constants $c_0,\dots, c_n$. In particular, every bounded distributional solution of
\begin{equation*}
    	(-\Delta)^{n/2}h=n!e^{nU}h\quad\hbox{in }\mathbb R^n,
\end{equation*}
    where $U(x)=\log\frac{2}{1+|x|^2}$, is of the form $h=\sum_{i=0}^nc_iZ_i$, where
    \begin{equation}\label{eq:kernel}
Z_0(x)=\frac{1-|x|^2}{1+|x|^2},\qquad
Z_i(x)=\frac{2x_i}{1+|x|^2}.
\end{equation}

\label{thm:main-bifur}
Let $n\ge3$ and let $k\ge2$ be an integer.
Then there exist $\varepsilon>0$ and a smooth curve
\begin{equation*}
 s\longmapsto(\alpha(s),\mathfrak u(s)), \qquad |s|<\varepsilon,    
\end{equation*}
of normal solutions of \eqref{eq:euclidean} such that
\begin{equation*}
 (\alpha(0),\mathfrak u(0))=(\alpha_{n,k},u_{\alpha_{n,k}})    
\end{equation*}
and $\mathfrak u(s)$ is nonradial for every sufficiently small $s\ne0$. Moreover, writing $x=r\omega$, we have
\begin{equation*}
 \mathfrak u(s)(r\omega)=u_{\alpha(s)}(r)+s\psi_{\alpha_{n,k},k}(\log r)Y_k(\omega)+o(s),    
\end{equation*}
where $Y_k\in\mathcal{H}_k$, $\psi_{\alpha_{n,k},k}>0$ spans $\operatorname{Ker} L_{\alpha_{n,k},k}$ and the remainder is $o(s)$ in $L^\infty(\mathbb R^n)$.

\label{lem:V infty}
Let $\gamma>0$. Let $u$ be a normal solution of \eqref{eq:euclidean} and let $V$ be given by \eqref{EF trans}. Then there exist constants $b_-, b_+\in \mathbb R$ such that uniformly in $\omega\in \mathbb S^{n-1}$,
    	\begin{equation}\label{V infty}
		\begin{aligned}
			V(t,\omega)=\alpha t+b_-+O(e^t),\quad
			&\partial_t V(t,\omega)=\alpha+O(e^t),&t\to-\infty,\\
			V(t,\omega)=-\alpha t+b_++O(e^{-t}),\quad
			&\partial_t V(t,\omega)=-\alpha+O(e^{-t}),&t\to+\infty.
		\end{aligned}
	\end{equation}
If $-1<\gamma\le 0$, then for $\delta<\min\{1, n\alpha\}$, \eqref{V infty} is still true if $O(e^{\pm t})$ is replaced by $O(e^{\pm \delta t})$ respectively. 

In particular, $\|\partial_t V\|_{L^\infty(\mathcal C)}<\infty$ and $e^{nV}\le Ce^{-n\alpha|t|}$.

Write $f(x)=|x|^{n\gamma}e^{nu(x)}$. Then $\int_{\mathbb R^n}f(x)\,\mathrm d x=\alpha|\mathbb S^n|$. The normal logarithmic behavior of $u$ implies that, for every sufficiently small $\varepsilon>0$,
	\begin{equation*}
		f(x)\leq C_\varepsilon |x|^{-n(1+\alpha)+\varepsilon},
		\qquad |x|\geq 1.
	\end{equation*}
	We first assume $\gamma>0$. Then since $n\alpha>2$, we can choose $\beta>0$ so that
	\begin{equation}\label{f decay}
		f(x)\leq C(1+|x|)^{-n-2-\beta}.
	\end{equation}

	We may therefore absorb the numerator in \eqref{rig:eq:normal-representation} into its constant and write
	\begin{equation}\label{u rep f}
		u(x)=c-\frac{2}{|\mathbb S^n|}\int_{\mathbb R^n}\log|x-y|\,f(y)\,dy
	\end{equation}
	Differentiation is legitimate by \eqref{f decay}. Hence
	\begin{equation}\label{grad u rep f}
		\nabla u(x)=-\frac{2}{|\mathbb S^n|}\int_{\mathbb R^n}\frac{x-y}{|x-y|^2}\,f(y)\,dy.
	\end{equation}

	To obtain the behavior at infinity, we rewrite \eqref{u rep f} as
    \begin{equation}\label{uneq 0rep f}
		u(x)=c-\frac{2}{|\mathbb S^n|}\int_{\mathbb R^n}\log\frac{|x-y|}{|x|}\,f(y)\,dy-2\alpha\log|x|, \qquad x\neq 0.
	\end{equation}
    For $r=|x|\geq 2$, we split $\mathbb R^n$ into
	\begin{equation*}
		\Omega_1=\{y: |y|<r/2\},\quad
		\Omega_2=\{y: |y|\geq r/2,\ |x-y|<r/2\},\quad
		\Omega_3=\{y: |y|\geq r/2,\ |x-y|\geq r/2\}.
	\end{equation*}
	On $\Omega_1$,
	\begin{equation*}
		\left|\log\frac{|x-y|}{r}\right|\leq C\frac{|y|}{r},
	\end{equation*}
    so
    \begin{equation*}
        \int_{\Omega_1}\left|\log\frac{|x-y|}{r}\right|f(y)\,dy\le \frac{C}{r}.
    \end{equation*}
	 On $\Omega_2$, \eqref{f decay} gives
	\begin{equation*}
		\begin{aligned}
			\int_{\Omega_2}
			\left|\log\frac{|x-y|}{r}\right|f(y)\,dy\leq Cr^{-2-\beta}
		\end{aligned}
	\end{equation*}
	On $\Omega_3$, we have
	\begin{equation*}
		\left|\log\frac{|x-y|}{r}\right|
		\leq C+\log\left(1+\frac{|y|}{r}\right),
	\end{equation*}
    so the integral on $\Omega_3$ is again $O(r^{-2-\beta})$. Consequently, for $b_+=c$, we have
	\begin{equation*}
	u(x)=-2\alpha\log|x|+b_++O(|x|^{-1}),\qquad x\to \infty.
	\end{equation*}
A similar analysis applied to \eqref{grad u rep f} gives
\begin{equation*}
    \nabla u(x)=-2\alpha\frac{x}{|x|^2}+O(|x|^{-2}), \qquad x\to \infty.
\end{equation*}

	At the origin, $C^1$ regularity (see \cite[Theorem 2.1]{HMM2021}) gives $u(x)=u(0)+O(|x|)$. Thus, writing $b_-=u(0)$ gives \eqref{V infty}.

    Finally, when $-1<\gamma\leq 0$, we take $\delta<\min\{1,n\alpha\}$. Then for $0<\varepsilon<n\alpha-\delta$, we have
    \begin{equation*}
        f(x)\le \begin{cases}
            C|x|^{n\alpha-n},\qquad |x|<1,\\
            C_\varepsilon |x|^{-n-n\alpha+\varepsilon}, \qquad |x|\ge 1.
        \end{cases}
    \end{equation*}
   For $r=|x|$ small, by splitting the logarithmic integral, we can obtain
    \begin{equation*}
        |u(x)-u(0)|+r|\nabla u(x)|\le Cr^{\delta}.
    \end{equation*}
    At infinity, following the previous argument, we use $\left|\log\frac{|x-y|}{r}\right|\leq C\frac{|y|}{r}\le C(\frac{|y|}{r})^\delta$ to obtain
    \begin{equation*}
        \int_{\Omega_1}\left|\log\frac{|x-y|}{r}\right|f(y)\,dy\le \frac{C}{r^\delta}.
    \end{equation*}
    Then the same splitting of integral gives
    \begin{equation*}
        |u(x)+2\alpha\log r-b_+|+|x\cdot \nabla u(x)+2\alpha|\le Cr^{-\delta}.
    \end{equation*}
    This gives the weaker asymptotics for $-1<\gamma\le 0$.

\label{rig:lem:translation-identity}
Let $u$ be a normal solution of \eqref{eq:euclidean} with $\gamma>0$ and let $f(x)=|x|^{n\gamma}e^{nu(x)}$. Then
\begin{equation}\label{rig:eq:inverse-moment}
 \int_{\mathbb R^n}\frac{x}{|x|^2}f(x)\,\mathrm d x=0.
\end{equation}

By \eqref{grad u rep f} and Fubini's theorem, we obtain
\begin{equation}\label{int f grad u=0}
     \int_{\mathbb R^n}f(x)\nabla u(x)\,\mathrm d x=-\frac{2}{|\mathbb S^n|}\iint \frac{x-y}{|x-y|^2}f(x)f(y)\,\mathrm d y\,\mathrm d x=0
\end{equation}
due to its antisymmetry in $x$ and $y$.

A direct computation gives
\begin{equation}\label{grad f}
    \nabla f=n\gamma\frac{x}{|x|^2} f+n f\nabla u.
\end{equation}
Since $\int_{\mathbb R^n}\nabla f \,\mathrm d x=0$, integrating \eqref{grad f} and using \eqref{int f grad u=0} gives  \eqref{rig:eq:inverse-moment}.

\label{lem:removability-normality}
Let $n\ge3$, $\gamma>-1$ and $u\in C^0(\mathbb R^n)$ satisfy
\begin{equation*}
     |u(x)|\le C(1+\log(1+|x|)).
\end{equation*}
Suppose that $|x|^{n\gamma}e^{nu}\in L^1(\mathbb R^n)$ and that $(-\Delta)^{n/2}u=(n-1)!|x|^{n\gamma}e^{nu}$ on $\mathbb R^n\setminus\{0\}$. Then the equation holds on $\mathbb R^n$ and $u$ is normal.

We first start the moving plane far to the left. We then show that it must stop at a finite position and prove that the stopping plane is a plane of symmetry by ruling out further continuation.
    \noindent\textbf{Step 1: Start of the moving plane.} 	For a real number $\lambda$, reflect in $t=\lambda$ and set
	\begin{equation*}
	t^\lambda=2\lambda-t,\qquad w_\lambda(t,\omega)=V(t^\lambda,\omega)-V(t,\omega) \quad(t<\lambda).
	\end{equation*}
	Then taking difference of the two representations in \eqref{int rep V} yields
	\begin{equation}\label{int rep w la}
		\begin{aligned}
			w_\lambda(t,\omega)
			&=\alpha\int_{s<\lambda}\int_{\mathbb S^{n-1}}K_\lambda(t,s,\omega\cdot\eta)\bigl(p(s^\lambda,\eta)-p(s,\eta)\bigr)\,d\eta\,ds\\
            &=\alpha\int_{s<\lambda}\int_{\mathbb S^{n-1}}K_\lambda(t,s,\omega\cdot\eta)p(s,\eta)\bigl(e^{nw_\lambda(s,\eta)}-1\bigr)\,d\eta\,ds,
		\end{aligned}
	\end{equation}
	where
	\begin{equation*}
		K_\lambda(t,s,a)
		=\log\frac{\cosh(2\lambda-t-s)-a}{\cosh(t-s)-a}.
	\end{equation*}

	For $t,s<\lambda$, $K_\lambda>0$ since $2\lambda-t-s>|t-s|$. To obtain an upper bound, we set $A=2\lambda-t-s$ and $D=|t-s|$. Then	for $a\in[-1,1]$ and $A, D>0$, we have elementary inequalities
	\begin{equation*}
		\begin{aligned}
			\cosh A-a\leq 2e^A,\qquad
			\cosh D-a\geq\cosh D-1\geq\frac{e^D}{2}(1-e^{-1})^2\min\{D^2,1\}.
		\end{aligned}
	\end{equation*}
  Therefore,
	\begin{equation}\label{K upper}
			0<K_\lambda(t,s,a)
			\leq 2(\lambda-s)+C_*+2\log^+\frac{1}{|t-s|},
			\qquad
			C_*=\log\frac{4}{(1-e^{-1})^2}.
	\end{equation}
	Here $\log^+r=\max\{\log r,0\}$. 

	We will use the following elementary bounds:
	\begin{equation}\label{log int}
		\int_\mathbb R\log^+\frac{1}{|t-s|}\,\mathrm d s=2,
	\end{equation}
	and, for every interval $I$ of length $0<\ell\leq1$,
	\begin{equation}\label{log int upper}
	\sup_{t\in\mathbb R}\int_I\log^+\frac{1}{|t-s|}\,\mathrm d s\leq\ell\left(1+\log\frac{2}{\ell}\right).
	\end{equation}


	To start the moving plane, we define
	\begin{equation*}
		N_\lambda=\{(s,\eta):s<\lambda,\ w_\lambda(s,\eta)<0\},
		\qquad w_\lambda^-=\max\{-w_\lambda,0\}.
	\end{equation*}
On $N_\lambda$, we have
	\begin{equation*}
1-e^{nw_\lambda(s,\eta)}=1-e^{-nw_\lambda^-(s,\eta)}\leq nw_\lambda^-(s,\eta).
	\end{equation*}
At a point where $w_\lambda(t,\omega)<0$, discarding the integral in \eqref{int rep w la} outside $N_\lambda$ yields
	\begin{equation}\label{w- le}
			w_\lambda^-(t,\omega)\leq n\alpha\int_{N_\lambda}K_\lambda(t,s,\omega\cdot\eta)p(s,\eta)
			w_\lambda^-(s,\eta)\,ds\,d\eta.
	\end{equation}

	For each fixed $\lambda$, the expansions \eqref{V infty} give $\lim_{t\to-\infty}w_\lambda(t,\omega)=b_+-b_--2\alpha\lambda$ uniformly in $\omega$. Together with continuity and $w_\lambda(\lambda,\omega)=0$ due to its definition, this proves that
	\begin{equation}\label{M la finite}
		M_\lambda:=\sup_{t<\lambda,\,\omega\in\mathbb S^{n-1}}w_\lambda^-(t,\omega)<\infty.
	\end{equation}

	For sufficiently negative $\lambda$, the bound $p(s,\eta)\leq Ce^{n\alpha s}$ holds for all $s<\lambda$. Using \eqref{log int}, the upper bound for $K_\lambda$ \eqref{K upper} gives
\begin{equation*}
	\begin{aligned}
	\sup_{t<\lambda,\,\omega}\int_{s<\lambda}\int_{\mathbb S^{n-1}}K_\lambda(t,s,\omega\cdot\eta)p(s,\eta)\,d\eta\,ds\leq C|\mathbb S^{n-1}|e^{n\alpha\lambda}\left(\frac{2}{(n\alpha)^2}+\frac{C_*}{n\alpha}+4\right)\longrightarrow0, \quad \lambda\to-\infty.
		\end{aligned}
\end{equation*}
	Consequently, for $\lambda_0$ negative enough, taking the supremum in \eqref{w- le} gives $M_\lambda\leq\frac{1}{2}M_\lambda$, so $w_\lambda\geq0$ for every $\lambda\leq\lambda_0$.	This starts the moving plane.
\medskip

    \noindent\textbf{Step 2: The stopping value and strict positivity.}
    Define the stopping value by
	\begin{equation}\label{def t0}
		t_0=\sup\Bigl\{\lambda\in\mathbb R:w_\mu(t,\omega)\geq0
		\text{ for every }\mu\leq\lambda,\ t<\mu,\ \omega\in\mathbb S^{n-1}\Bigr\}.
	\end{equation}
 By \eqref{V infty},	$\lim_{t\to-\infty}w_\lambda(t,\omega)=b_+-b_--2\alpha\lambda<0$	for sufficiently large $\lambda$, so $t_0$ is finite. By continuity,	$w_{t_0}(t,\omega)\geq0$ for all $t<t_0$. Our goal is to prove that $w_{t_0}\equiv 0$ and then the symmetry follows.

	Suppose, for contradiction, that $w_{t_0}$ is not identically zero. It is then positive on a nonempty open subset. On that subset $	p(s,\eta)\bigl(e^{nw_{t_0}(s,\eta)}-1\bigr)>0$. Since $K_{t_0}>0$ by \eqref{K upper}, the integral representation \eqref{int rep w la} then yields
	\begin{equation}\label{w>0 strict}
		w_{t_0}(t,\omega)>0\quad\text{for every }t<t_0,\ \omega\in\mathbb S^{n-1}.
	\end{equation}
We now show that this contradicts the definition of $t_0$.
    \medskip

    \noindent\textbf{Step 3: Excluding further continuation.}
    For $\lambda>t_0$ close to $t_0$, we divide the left half-cylinder into the three regions
\begin{equation*}
 (-\infty,-T)\times\mathbb S^{n-1},\qquad
 [-T,t_0-\delta]\times\mathbb S^{n-1},\qquad
 (t_0-\delta,\lambda)\times\mathbb S^{n-1}.   
\end{equation*}

Strict positivity of $w_{t_0}$ and continuity preserve positivity on the middle region. On the other two regions, choosing $T$ large and $\delta$ small makes the kernel integrals sufficiently small to exclude a negative part by \eqref{w- le}.

We first provide a uniform estimate for the integral over $(-\infty,-T)\times\mathbb S^{n-1}$. To this end, we choose $T>|t_0|+2$ sufficiently large that $p(s,\eta)\leq Ce^{n\alpha s}$ for all $s<-T$. For all $\lambda\in[t_0,t_0+1]$, we have
	\begin{equation*}
	\int_{s<-T}\int_{\mathbb S^{n-1}}\bigl(2(\lambda-s)+C_*\bigr)p(s,\eta)\,d\eta\,ds\leq C\int_{-\infty}^{-T}(1+|s|)e^{n\alpha s}\,ds
	\leq C(1+T)e^{-n\alpha T}.
	\end{equation*}
	For the logarithmic part, we have
	\begin{equation*}
		\int_{s<-T}\int_{\mathbb S^{n-1}}\log^+\frac{1}{|t-s|}\,p(s,\eta)\,d\eta\,ds
        \leq Ce^{-n\alpha T}\int_{\mathbb R}\log^+\frac{1}{|t-s|}\,ds=2Ce^{-n\alpha T}.
	\end{equation*}
uniformly in $t$. Consequently, (\ref{K upper}) implies 
	\begin{equation}\label{int far left}
		\sup_{\substack{t_0\leq\lambda\leq t_0+1\\t<\lambda,\ \omega\in\mathbb S^{n-1}}}\int_{s<-T}\int_{\mathbb S^{n-1}}K_\lambda(t,s,\omega\cdot\eta)p(s,\eta)\,d\eta\,ds
		\leq C(1+T)e^{-n\alpha T}.
	\end{equation}

We also need an estimate on $(t_0-\delta,\lambda)\times\mathbb S^{n-1}$. Let $0<\delta<1/4$ and $\lambda\in[t_0,t_0+\delta]$. Set
	\begin{equation*}
		I=(t_0-\delta,\lambda),\qquad \ell=|I|\leq2\delta<1.
	\end{equation*}
	On this strip $0<\lambda-s<\ell$. Since $p$ is bounded, \eqref{K upper} and \eqref{log int upper} imply
	\begin{equation}\label{int strip}
		\begin{aligned}
			\sup_{t<\lambda,\,\omega}
			&\int_{t_0-\delta<s<\lambda}\int_{\mathbb S^{n-1}}K_\lambda(t,s,\omega\cdot\eta)p(s,\eta)\,d\eta\,ds\\
			&\quad\leq\|p\|_\infty|\mathbb S^{n-1}|\left[\ell^2+C_*\ell+2\ell\left(1+\log\frac{2}{\ell}\right)\right]\\
			&\quad\leq C\delta(1+|\log\delta|).
		\end{aligned}
	\end{equation}

	Now we fix $T$ large enough and $\delta$ small enough such that the integrals in \eqref{int far left} and \eqref{int strip} are less than $\frac{1}{4n\alpha}$. Then by the compactness of $[-T,t_0-\delta]\times\mathbb S^{n-1}$ and \eqref{w>0 strict}, we get
	\begin{equation*}
		m:=\min_{[-T,t_0-\delta]\times\mathbb S^{n-1}}w_{t_0}>0.
	\end{equation*}
Moreover,
	\begin{equation*}
	|w_\lambda(t,\omega)-w_{t_0}(t,\omega)|=|V(2\lambda-t,\omega)-V(2t_0-t,\omega)|\leq2\|\partial_t V\|_\infty|\lambda-t_0|.
	\end{equation*}

	Choose
	\begin{equation*}
		0<\varepsilon\leq\min\left\{\delta,\frac{m}{4(1+\|\partial_t V\|_\infty)}\right\}.
	\end{equation*}
	Then for every $\lambda\in[t_0,t_0+\varepsilon]$,
	\begin{equation*}
		w_\lambda\geq\frac{m}{2}\quad\text{on }[-T,t_0-\delta]\times\mathbb S^{n-1}.
	\end{equation*}
	Therefore its negative set satisfies
	\begin{equation*}
		N_\lambda\subset\bigl(( -\infty,-T)\cup(t_0-\delta,\lambda)\bigr)\times\mathbb S^{n-1}.
	\end{equation*}


	By our choices of $T$, $\delta$, and $\varepsilon$, we obtain
	\begin{equation*}
n\alpha\sup_{t<\lambda,\,\omega}\int_{N_\lambda}K_\lambda(t,s,\omega\cdot\eta)p(s,\eta)\,ds\,d\eta<\frac{1}{2}
	\end{equation*}
	 for every $\lambda\in[t_0,t_0+\varepsilon]$. By \eqref{w- le} and \eqref{M la finite},
	\begin{equation*}
		w_\lambda^-(t,\omega)\leq n\alpha M_\lambda\int_{N_\lambda}K_\lambda p\,\mathrm d s\,\mathrm d\eta
	\leq\frac{1}{2}M_\lambda.
	\end{equation*}
	Taking the supremum yields $M_\lambda\leq\frac{1}{2}M_\lambda$, so $M_\lambda=0.$ Consequently, $w_\lambda\geq0$ for every $\lambda\in [t_0,t_0+\varepsilon]$, which contradicts the definition of $t_0$ \eqref{def t0}. 

    Therefore, we proved that $w_{t_0}\equiv0$, which is exactly \eqref{V sym}. As a result, \eqref{u kelvin} holds for $R=e^{t_0}$. Finally, \eqref{R half mass} follows from a simple change of variable.

\label{coro:translation-identity}
Let $u$ be a normal solution of \eqref{eq:euclidean} with $\gamma>0$ and let $f(x)=|x|^{n\gamma}e^{nu(x)}$. Then
\begin{equation*}
 \int_{\mathbb R^n}xf(x)\,\mathrm d x=0.
\end{equation*}

\label{lem:radial-kernel-g}
	Let
	\begin{equation*}
	f_n(s)=e^{-2s}(1-e^{-2s})^{n/2-2}\mathbf 1_{(0,\infty)}(s),
	\qquad
	\widetilde f_n(s)=f_n(-s).
	\end{equation*}
	Then 
	\begin{equation}\label{eq:g-autocorrelation-revised}
		g_n=d_n f_n*\widetilde f_n,
	\end{equation}
    where $d_n=\frac{2^{4-n}}{\Gamma(n/2-1)^2}$.	Consequently, $g_n$ is even and positive, and $g_n(t)\le Ce^{-2|t|}$ for $|t|\ge1$ and some constant $C>0$. The integral of $g_n$ on $\mathbb{R}$ is
\begin{equation}\label{int gn}
		\int_\mathbb R g_n(t)\,\mathrm d t=\frac{1}{\beta_n}.
	\end{equation}
 Moreover, $g_n'(t)<0$ for $t>0$. For $n=3$, $g_3$ has a logarithmic singularity at the origin and is smooth away from it.

\label{prop:coercivity}
	Let $\rho$ be a probability measure translated so that $0$ is its median, that is,
\begin{equation}\label{0 median}
\rho\bigl((-\infty,0]\bigr)\ge\frac{1}{2}\text{ and } \rho\bigl([0,\infty)\bigr)\ge\frac{1}{2}.
\end{equation}
	 Then
	\begin{equation*}
	\mathcal F_{n,\alpha}(\rho)
	\ge c\int_\mathbb R|t|\rho(t)\,\mathrm d t-C
	\end{equation*}
	for constants $c,C>0$ depending only on $n$ and $\alpha$.

By \eqref{0 median}, we obtain
	\begin{equation*}
		\iint_{\mathbb R^2}|t-s|\rho(t)\rho(s)\,\mathrm d t \,\mathrm d s
		\ge\frac{1}{2}\int_\mathbb R|t|\rho(t) \,\mathrm d t.
	\end{equation*}
From \eqref{eq:K-linear-revised}, we have $\mathcal K_n(t)\ge \frac{|t|}{2\beta_n} -C_0$. Therefore,
\begin{equation}\label{int ge}
	\iint_{\mathbb R^2}\mathcal K_n(t-s)\rho(t)\rho(s)\,\mathrm d t\,\mathrm d s \ge \frac{1}{4\beta_n}\int_\mathbb R|t|\rho(t) \,\mathrm d t-C_0.
\end{equation}



	For $\sigma>0$, we define an auxiliary function
    \begin{equation*}
		q_\sigma(t)=\frac{\sigma}{2}e^{-\sigma|t|},
	\end{equation*} 
    Since $x\mapsto x\log x$ is convex on $(0,\infty)$ and its derivative is $1+\log x$, we have
\begin{equation}\label{xlogx convex}
 x\log x\ge y\log y+(1+\log y)(x-y)
 =x\log y+x-y \text{ for }x\ge0\text{ and }y>0,   
\end{equation}
where the case $x=0$ follows by continuity. Taking $x=\rho(t)$ and $y=q_\sigma(t)>0$ gives
\[
 \rho(t)\log\rho(t)
 \ge \rho(t)\log q_\sigma(t)+\rho(t)-q_\sigma(t).
\]
	Integrating, we obtain
	\begin{equation}\label{ent ge}
			\int_{\mathbb R}\rho\log\rho\,\mathrm d t
		\ge\log\frac\sigma2-\sigma\int_{\mathbb R}|t|\rho(t)\,\mathrm d t.
	\end{equation}
	Combining \eqref{int ge} and \eqref{ent ge}, the assertion follows by choosing $0<\sigma<\frac{C_{n,\alpha}}{8\beta_n}$.

Choose a minimizing sequence $\rho_j$ and translate each density so that $0$ is a median, as in \eqref{0 median}. Proposition~\ref{prop:coercivity} gives
\[
 \sup_j\int_\mathbb R |t|\rho_j(t)\,\mathrm d t\le M_0<\infty.
\]
By Prokhorov's theorem \cite[Theorem~3.10.3]{Durrett2019}, after passing to a subsequence, the probability measures $\rho_j(t)\,\mathrm d t$ converge weakly to a probability measure $\mu$, with
$\int_\mathbb R|t|\,\mathrm d\mu(t)\le M_0$.

Since $\mathcal{K}_n\geq 0$, the minimizing sequence satisfies $\operatorname{Ent}(\rho_j)\le \mathcal{F}_{n,\alpha}\le C$. By the lower semicontinuity of the entropy on measures with uniformly bounded first moments (see \cite[Proposition 2.1 (1)--(2)]{Santambrogio2016}), we have
\begin{equation*}
    \operatorname{Ent}(\mu)\le \liminf_{j\to\infty}\operatorname{Ent}(\rho_j)\le C.
\end{equation*}
Therefore $\mu=\rho\,\mathrm d t$ for some density $\rho$ in $\mathcal{P}_1(\mathbb R)$.

Since $\mathcal K_n$ is continuous and nonnegative, weak convergence of the product measures also yields
\begin{equation*}
    \iint_{\mathbb R^2}\mathcal K_n(t-s)\rho(t)\rho(s)\,\mathrm d t\,\mathrm d s
 \le\liminf_{j\to\infty}\iint_{\mathbb R^2}\mathcal K_n(t-s)\rho_j(t)\rho_j(s)\,\mathrm d t\,\mathrm d s.
\end{equation*}
Combining these inequalities shows that $\rho$ is a minimizer with finite entropy and finite first moment. 

Moreover, since
\begin{equation*}
 (\mathcal K_n*\rho)(t)=\frac{|t|}{2\beta_n}+O(1),    
\end{equation*}
the probability density
\begin{equation*}
 \bar\rho(t):=\frac{\exp(-C_{n,\alpha}(\mathcal K_n*\rho)(t))}{\int_\mathbb R\exp(-C_{n,\alpha}(\mathcal K_n*\rho)(s))\,\mathrm d s}    
\end{equation*}
is well defined and satisfies $c e^{-n\alpha|t|}\le\bar\rho(t)\le C e^{-n\alpha|t|}$ for $t\in\mathbb R$ and some $c, C>0$.  For $\rho_\varepsilon=(1-\varepsilon)\rho+\varepsilon\bar\rho$ and $\delta=\bar\rho-\rho$, convexity of the entropy and expansion of the interaction term give
\begin{equation*}
    \begin{aligned}
      0\le\mathcal F_{n,\alpha}(\rho_\varepsilon)
 -\mathcal F_{n,\alpha}(\rho)
 \le&\varepsilon \left(\operatorname{Ent}(\bar\rho)-\operatorname{Ent}(\rho)+C_{n,\alpha}\int_{\mathbb R}(\mathcal K_n*\rho)\delta\,\mathrm d t\right)\\
 &+\frac{C_{n,\alpha}\varepsilon^2}{2} \iint_{\mathbb R^2}\mathcal K_n(t-s)\delta(t)\delta(s)\,\mathrm d t\,\mathrm d s\\
 =&-\varepsilon\int_\mathbb R\rho\log\frac{\rho}{\bar\rho}\,\mathrm d t+O(\varepsilon^2).   
    \end{aligned}
\end{equation*}
The remainder is finite because both densities have finite first moment and $\mathcal K_n$ has at most linear growth. Dividing by $\varepsilon$ and letting $\varepsilon\downarrow0$ and applying inequality \eqref{xlogx convex}, we obtain that  $\rho=\bar\rho$ almost everywhere. Thus $\rho$ has a positive continuous representative and satisfies \eqref{eq:density-EL}.

With $M_\alpha$ as in \eqref{def M rho C}, set $v_\alpha=n^{-1}\log(M_\alpha\rho)$. Then \eqref{eq:K-fundamental-revised} gives \eqref{eq:radial-equation}. The symbol $a_{n,0}$ is elliptic of order $n$, so local elliptic regularity \cite[Theorem~18.1.29]{HormanderIII} first gives $v_\alpha\in H^n_{\mathrm{loc}}(\mathbb R)$, since $e^{nv_\alpha}\in L^2_{\mathrm{loc}}(\mathbb R)$.
Iterating this regularity gain together with Sobolev composition gives $v_\alpha\in H^{kn}_{\mathrm{loc}}(\mathbb R)$ for every integer $k\ge1$ and hence $v_\alpha\in C^\infty(\mathbb R)$. Using \eqref{eq:K-linear-revised} and the finite first moment of $\rho$, we obtain the following asymptotics by the dominated convergence theorem:
\begin{equation}\label{eq:v toinfty}
 v_\alpha(t)=
 \begin{cases}
  \alpha t+c_-+o(1),&t\to-\infty,\\
  -\alpha t+c_++o(1),&t\to+\infty.
 \end{cases}
\end{equation}
Differentiating \eqref{eq:density-EL} also gives
\eqref{eq:v al infty}.
Consequently,
\[
 u_\alpha(x)=v_\alpha(\log|x|)-\alpha\log|x|
\]
is continuous on $\mathbb R^n$ with $u_\alpha(0)=c_-$, has at most logarithmic growth and
\[
 \int_{\mathbb R^n}|x|^{n\gamma}e^{nu_\alpha}\,\mathrm d x=|\mathbb S^{n-1}|M_\alpha<\infty.
\]
The Emden--Fowler transformation gives the equation away from the origin and Lemma~\ref{lem:removability-normality} shows that $u_\alpha$ is a radial normal solution on $\mathbb R^n$.

We first claim that $\int_\mathbb R W_\alpha(t)\phi(t)\,\mathrm d t=0$. In fact, the function $h:=\phi+\mathcal{K}_n*(W_\alpha\phi)$ satisfies $A_{n,0}h=0$ and it is a tempered distribution because of the exponential decay of $W_\alpha$ and the boundedness of $\phi$. By Lemma \ref{lem:tempered-radial-kernel}, $h=at+b$ for some $a, b\in\mathbb R$.

On the other hand, by \eqref{eq:K-linear-revised}, the dominated convergence theorem gives
\begin{equation*}
\frac{(\mathcal{K}_n* (W_\alpha\phi))(t)}{t}\longrightarrow
\begin{cases}
	\frac{1}{2\beta_n} \int_\mathbb R W_\alpha(s)\phi(s)\,\mathrm d s,&t\to+\infty,\\
	-\frac{1}{2\beta_n} \int_\mathbb R W_\alpha(s)\phi(s)\,\mathrm d s,&t\to-\infty.
\end{cases}
\end{equation*}
Since $\phi$ is bounded, we must have $\int_\mathbb R W_\alpha(t)\phi(t)\,\mathrm d t=0$.

Set $\sigma(t)=W_\alpha(t)\phi(t)$. Then $\int_{\mathbb R}\sigma(t)\,\mathrm d t=0$ and the equation for $\phi$ gives
\begin{equation}\label{eq:sigma}
	\frac{\sigma}{\rho_\alpha}
	+C_{n,\alpha}\mathcal{K}_n*\sigma=\text{constant}.
\end{equation}
Define $\zeta(t):=-\frac{1}{\rho_\alpha(t)} \int_{-\infty}^t\sigma(s)\,\mathrm d s$. Then $\sigma=-(\rho_\alpha\zeta)'$. Since $\sigma=C_{n,\alpha}\rho_\alpha\phi$ and $\int_\mathbb R\sigma=0$, for $t\ge0$ we have
\begin{equation*}
    |\zeta(t)|=\frac{\left|\int_t^\infty\sigma(s)\,\mathrm d s\right|}{\rho_\alpha(t)}
 \le C_{n,\alpha}\|\phi\|_\infty\frac{\int_t^\infty\rho_\alpha(s)\,\mathrm d s}{\rho_\alpha(t)}
 \le C.
\end{equation*}
Here the last inequality follows from $\rho_\alpha(t)\sim e^{-n\alpha|t|}$ due to  \eqref{def M rho C} and \eqref{eq:v toinfty}. For $t\le0$, the same estimate follows directly from the defining integral over $(-\infty,t]$. Thus $\zeta$ is bounded.
Differentiating its definition gives
\begin{equation*}
    \zeta'=-\frac{\sigma}{\rho_\alpha}-\frac{\rho_\alpha'}{\rho_\alpha}\zeta
 =-C_{n,\alpha}\phi-nv_\alpha'\zeta.
\end{equation*}
Since $\phi$, $v_\alpha'$ and $\zeta$ are bounded, so is $\zeta'$. 

We have the following key identity.
\begin{equation}\label{Q al id}
	\begin{aligned}
		\mathcal Q_\alpha[\zeta]
		:=&\int_\mathbb R\rho_\alpha(t)|\zeta'(t)|^2\,\mathrm d t+\frac{C_{n,\alpha}}2
		\iint_{\mathbb R^2}g_n(t-s)
		|\zeta(t)-\zeta(s)|^2\rho_\alpha(t)\rho_\alpha(s)\,\mathrm d t\,\mathrm d s\\
		=& \int_\mathbb R \rho_\alpha\zeta(\frac{\sigma}{\rho_\alpha}
		+C_{n,\alpha}\mathcal{K}_n*\sigma)'\,\mathrm d t.
	\end{aligned}
\end{equation}
Indeed, using integration by parts, we can write
\begin{equation}\label{Q al 1}
	\begin{aligned}
	\int_\mathbb R \rho_\alpha\zeta(\frac{\sigma}{\rho_\alpha})'\,\mathrm d t=&\int_\mathbb R \rho_\alpha\zeta\left(-\zeta'-(\log\rho_\alpha)'\zeta\right)'\,\mathrm d t\\
	=&\int_\mathbb R\rho_\alpha|\zeta'|^2\,\mathrm d t-\int_\mathbb R (\log\rho_\alpha)''\rho_\alpha\zeta^2\,\mathrm d t\\
	=&\int_\mathbb R\rho_\alpha|\zeta'|^2\,\mathrm d t+C_{n,\alpha}\iint g_n(t-s)	\rho_\alpha(t)\rho_\alpha(s)\zeta(t)^2\,\mathrm d t\,\mathrm d s,
	\end{aligned}
\end{equation}
where we used the equation $(\log\rho_\alpha)''=-C_{n,\alpha}g_n*\rho_\alpha$ in the last equality.


On the other hand, integration by parts gives
\begin{equation*}
	(\mathcal{K}_n'*\sigma)(t)
	=-\int_\mathbb R g_n(t-s)\rho_\alpha(s)\zeta(s)\,\mathrm d s,
\end{equation*}
so
\begin{equation}\label{Q al 2}
	C_{n,\alpha}\int_\mathbb R\rho_\alpha(t)\zeta(t)(\mathcal{K}_n'*\sigma)(t)\,\mathrm d t
	=-C_{n,\alpha}\iint_{\mathbb R^2} g_n(t-s)
	\rho_\alpha(t)\rho_\alpha(s)\zeta(t)\zeta(s)\,\mathrm d t\,\mathrm d s.
\end{equation}
\eqref{Q al id} then follows from \eqref{Q al 1} and \eqref{Q al 2}.


By \eqref{eq:sigma}, integration by parts once more yields that $\mathcal{Q}_\alpha[\zeta]=0$, so $\zeta$ is constant. Hence $\sigma=-c\rho_\alpha'$. Since $W_\alpha=n!M_\alpha\rho_\alpha$, we obtain that
\begin{equation*}
	\phi=\frac{\sigma}{W_\alpha}=-\frac{c}{n!M_\alpha}\frac{\rho_\alpha'}{\rho_\alpha}=-\frac{c}{(n-1)!M_\alpha}v_\alpha'.
\end{equation*}

\label{prop:mode-green}
For $n\ge3$, $k\ge1$ and $t\ge0$, we have
\begin{align}
 G_{n,k}(t)
 &=\frac{2^{1-n}e^{-kt}}{\Gamma(n/2)^2}
 \int_0^1s^{k-1}(1-s)^{n/2-1}
 (1-e^{-2t}s)^{n/2-1}\,\mathrm d s,
 \label{eq:G-beta}\\
 &=\frac{2^{1-n}\Gamma(k)}{\Gamma(n/2)\Gamma(k+n/2)}e^{-kt}
 \,{}_2F_1\left(1-\frac n2,k;k+\frac n2;e^{-2t}\right).
 \label{eq:G-hyper}
\end{align}
Moreover,
\begin{equation}\label{eq:G-diagonal}
 G_{n,k}(0)=
 \frac{2^{1-n}\Gamma(k)\Gamma(n-1)}
 {\Gamma(n/2)^2\Gamma(n+k-1)}.
\end{equation}
The function $G_{n,k}$ is even, strictly positive and strictly
decreasing on $(0,\infty)$. Moreover,
\begin{equation}\label{eq:G-positive-minors}
 \det\bigl[G_{n,k}(t_i-s_j)\bigr]_{i,j=1}^2>0
 \qquad
 \text{whenever }t_1<t_2\text{ and }s_1<s_2.
\end{equation}

Let $\{e_j\}_{j=1}^\infty$ be an orthonormal basis of a Hilbert space with inner product $\langle \cdot ,\cdot \rangle$. An operator $T$ is \emph{Hilbert--Schmidt} if
\begin{equation*}
	\left\lVert T\right\rVert_{\mathfrak S_2}^2:=\sum_{j=1}^\infty \|Te_j\|^2<\infty.
\end{equation*}
$T$ is \emph{trace class} if
\begin{equation*}
	\left\lVert T\right\rVert_{\mathfrak S_1}:= \operatorname{tr}(\sqrt{T^*T})<\infty,
\end{equation*}
where the \emph{trace} is 
\begin{equation*}
	\operatorname{tr}(T)=\sum_{j=1}^\infty\langle Te_j, e_j\rangle.
\end{equation*}

\label{prop:BS-basic}
	For every $n\ge3$, $\alpha>0$ and $k\ge1$, the operator $\mathscr K_{\alpha,k}$ is positive, self-adjoint, compact, trace class, injective and positivity-improving in the sense that
	\begin{equation*}
		  f\ge0,\ f\not\equiv0
		\quad\Longrightarrow\quad
		\mathscr{K}_{\alpha,k}f>0\quad\text{on }\mathbb R. 
	\end{equation*}
	Its trace is
	\begin{equation}\label{eq:exact-trace}
		\operatorname{tr}\mathscr K_{\alpha,k}
		=\frac{\alpha}{\mathfrak a_{n,k}},
	\end{equation}
	where $\mathfrak a_{n,k}$ is defined in \eqref{def ak bk}. Its principal eigenvalue $\mu_1(\alpha,k)$ is simple and has a strictly positive eigenfunction. $\mathscr K_{\alpha,k}$ is strictly totally positive of order two in the sense of Definition \ref{def:TP2}. Moreover,
	\begin{equation}\label{equiv L K}
	0\in\sigma(L_{\alpha,k})
	\quad\Longleftrightarrow\quad
	1\in\sigma(\mathscr K_{\alpha,k}),
	\end{equation}
and multiplicities agree.

Let $T_{\alpha,k}=A_{n,k}^{-\frac{1}{2}}W_\alpha^{\frac{1}{2}}$.  Then $\mathscr K_{\alpha,k}=T_{\alpha,k}^*T_{\alpha,k}$. Let $Q_{n,k}$ be the convolution kernel of $A_{n,k}^{-\frac{1}{2}}$.  By Plancherel's identity,
	\begin{equation*}
	\int_\mathbb R|Q_{n,k}(t)|^2\,\mathrm d t
	=\frac1{2\pi}\int_\mathbb R\frac{\,\mathrm d\xi}{a_{n,k}(\xi)}
	=G_{n,k}(0).
	\end{equation*}
	Consequently, since  $W_\alpha\in L^1$, we get
	\begin{align*}
		\left\lVert T_{\alpha,k}\right\rVert_{\mathfrak S_2}^2=\iint_{\mathbb R^2}		|Q_{n,k}(t-s)|^2W_\alpha(s)\,\mathrm d s\,\mathrm d t=G_{n,k}(0)\int_\mathbb R W_\alpha(s)\,\mathrm d s<\infty.
	\end{align*}
	$T_{\alpha,k}$ is Hilbert--Schmidt by	\cite[Theorem~VI.23]{ReedSimonI} and compact by	\cite[Theorem~VI.22(e)]{ReedSimonI}. Hence $\mathscr K_{\alpha,k}=T_{\alpha,k}^*T_{\alpha,k}$ is trace class.  Moreover,
	\begin{equation*}
	\operatorname{tr}\mathscr K_{\alpha,k}
	=\left\lVert T_{\alpha,k}\right\rVert_{\mathfrak{S}_2}^2
	=G_{n,k}(0)\int_\mathbb R W_\alpha(t)\,\mathrm d t.
	\end{equation*}
	Substituting \eqref{eq:G-diagonal} and \eqref{eq:W-mass} gives \eqref{eq:exact-trace}.

	Positivity and self-adjointness follow from the factorization.  Since $W_\alpha>0$ and $A_{n,k}^{-\frac{1}{2}}$ is injective, $T_{\alpha,k}$ and hence $\mathscr K_{\alpha,k}$ are injective. The integral kernel \eqref{int kernel K} is strictly positive, so $\mathscr{K}_{\alpha,k}$ is positivity-improving. The Perron--Frobenius theorem for compact positivity-improving operators	\cite[Theorem~V.6.6, p.~337]{Schaefer1974} then shows that its principal eigenvalue is simple and has a strictly positive eigenfunction.

		By \eqref{eq:G-positive-minors}, for $t_1<t_2$ and $s_1<s_2$,
\[
 \begin{aligned}
 \det\left[
 W_\alpha(t_i)^{1/2}G_{n,k}(t_i-s_j)
 W_\alpha(s_j)^{1/2}
 \right]_{i,j=1}^2=
 \prod_{i=1}^2
 \bigl[W_\alpha(t_i)W_\alpha(s_i)\bigr]^{1/2}
 \det\bigl[G_{n,k}(t_i-s_j)\bigr]_{i,j=1}^2>0.
 \end{aligned}
\]
Thus the integral kernel \eqref{int kernel K} satisfies
Definition~\ref{def:TP2}.

	Finally, \eqref{equiv L K} follows directly from the definition.

Let $\varphi$ be a bounded distributional solution of $L_{\alpha,k}\phi=0$. Since $W_\alpha\in L^2(\mathbb R)\cap L^\infty(\mathbb R)$, we have $W_\alpha\phi\in L^2(\mathbb R)$. By \eqref{eq:mode-symbol},
    \begin{equation*}
        a_{n,k}(\xi)\ge c_{n,k}(1+|\xi|^2)^{\frac{n}{2}}.
    \end{equation*}
    Therefore $\psi:=A_{n,k}^{-1}(W_\alpha\phi)\in H^n(\mathbb R)$. The difference $\phi-\psi$ is a tempered distribution and satisfies $a_{n,k}(\xi)(\widehat{\phi-\psi})=0$. Since $a_{n,k}$ is positive and smooth, we conclude that $\phi=\psi$. 

    Conversely, if $\mathscr{K}_{\alpha,k}\varphi=\varphi$ for some $\varphi\in L^2(\mathbb R)$, then $\phi:=A_{n,k}^{-1}(W_\alpha^{1/2} \varphi)\in H^n(\mathbb R)$ and $L_{\alpha,k}\phi=0$. The boundedness of $\phi$ then follows from the embedding $H^n(\mathbb R)\subset L^\infty(\mathbb R)$.

\label{lem:order-two-oscillation}
	Let $T$ be a compact, injective, positive, self-adjoint integral operator on $L^2(\mathbb R)$ with a continuous symmetric kernel $K$ that is strictly totally positive of order two. Assume $T$ is trace class. Let
	\begin{equation*}
	\mu_1>\mu_2\ge\mu_3\ge\cdots>0
	\end{equation*}
	be its eigenvalues.  Then $\mu_2$ is simple.  If $\phi_1>0$ and $\phi_2$ are eigenfunctions corresponding to $\mu_1$ and $\mu_2$, respectively, then $\frac{\phi_2}{\phi_1}$ is strictly monotone and $\phi_2$ has exactly one sign change.

Let
	\begin{equation*}
	\Omega_2=\{(t_1,t_2)\in\mathbb R^2:t_1<t_2\}.
	\end{equation*}
For $(t_1,t_2),(s_1,s_2)\in\Omega_2$, we define
	\begin{equation*}
\mathcal{D}(t_1,t_2;s_1,s_2):=	\det\bigl(K(t_i,s_j)\bigr)_{i,j=1}^2=K(t_1,s_1)K(t_2,s_2)-K(t_1,s_2)K(t_2,s_1).
	\end{equation*}
	By its positivity, we get $\mathcal{D}>0$. We consider the operator $\mathcal{T}$ on $L^2(\Omega_2)$ defined by
	\begin{equation*}
		(\mathcal{T}F)(t_1,t_2):=\int_{\Omega_2}\mathcal{D}(t_1,t_2;s_1,s_2)F(s_1,s_2)\,\mathrm d s_1\,\mathrm d s_2.
	\end{equation*}
	Then $\mathcal{T}$ is self-adjoint and compact.

	We next describe the eigenfunctions of $\mathcal{T}$. Let $\phi_j$ be a normalized eigenfunction of $T$ corresponding to $\mu_j$. Let
	\begin{equation*}
		\psi_{ij}(t_1,t_2)=\phi_i(t_1)\phi_j(t_2)-\phi_i(t_2)\phi_j(t_1).
	\end{equation*} 
	Then it is straightforward to show that $ \mathcal{T}\psi_{ij}=\mu_i\mu_j\psi_{ij}$. On the other hand, by extending the functions in $\Omega_2$ to $\mathbb R^2$ antisymmetrically, we see that $\{\psi_{ij}: i<j\}$ is an orthogonal basis of $L^2(\Omega_2)$. Therefore, the eigenvalues of $\mathcal{T}$ are $\mu_i\mu_j$, $i<j$.

	As a result, the principal eigenvalue of $\mathcal{T}$ is $\mu_1\mu_2$ and is simple. Since $\mu_1$ is a simple eigenvalue of $T$, it follows that $\mu_2$ is simple.

	After choosing the sign of $\phi_2$, we may assume the principal eigenfunction $\psi_{12}$ is positive. Since $\phi_1>0$, the ratio $\frac{\phi_2}{\phi_1}$ is strictly increasing.  Orthogonality
	\begin{equation*}
	\int_\mathbb R\phi_1(t)\phi_2(t)\,\mathrm d t=0
	\end{equation*}
	forces $\frac{\phi_2}{\phi_1}$ to take both signs.  Strict monotonicity then gives exactly one zero and exactly one sign change of $\phi_2$.

\label{thm:mu2}
If $\mu_1(\alpha,k)>\mu_2(\alpha,k)\ge\cdots$ are the eigenvalues of $\mathscr K_{\alpha,k}$, then
\begin{equation*}
 \mu_2(\alpha,k)<1 \quad\hbox{for every }n\ge3,\ \alpha>0,\ k\ge1.
\end{equation*}
Consequently $L_{\alpha,k}$ has Morse index at most one. If zero is an eigenvalue of $L_{\alpha,k}$, then it is the principal eigenvalue and is simple. 
Moreover, let $\psi_{\alpha,k}>0$ be the even principal generalized eigenfunction, that is,
\begin{equation}\label{eq:generalized-eigenpair}
A_{n,k}\psi_{\alpha,k}=\tau_{\alpha,k}W_\alpha\psi_{\alpha,k}, \qquad\tau_{\alpha,k}=\mu_1(\alpha,k)^{-1}.
\end{equation}
Then $\partial_t\psi_{\alpha,k}(t)<0$ for $t>0$.

\label{lem:monotone mu}
	\begin{equation}\label{eq:mu-kappa-decreasing}
		\kappa\longmapsto\mu_1(\alpha,\kappa) \quad\text{is strictly decreasing}.
	\end{equation}
	$\mu_1(\alpha,\kappa)$ is differentiable with respect to $\alpha$ and
	\begin{equation}\label{eq:mu-al-increasing}
		\partial_\alpha\mu_1(\alpha,\kappa)>0.
	\end{equation}

\label{lem:H-representations}
	Let
\begin{equation*}
a=\frac{n-2}{2}, \qquad q=e^{-2t},\qquad x=\operatorname{sech}^2t=\frac{4q}{(1+q)^2}.
\end{equation*}
	For $t>0$, we have the representations
	\begin{align}
		H_n(t)&=2a\int_0^1(1-s)^{a-1}(1-qs)^a\,\mathrm d s-1,\label{eq:H-beta}\\
		&=\tanh t\,F_a(x),		\label{eq:H-hyper}
	\end{align}
	where $F_a(x)=\,{}_2F_1\left(\frac{1}{2},1;a+1;x\right)$. Moreover,
	\begin{equation}\label{eq:F-first-order}
		x(1-x)F_a'(x)+\left(a-\frac x2\right)F_a(x)=a,
	\end{equation}
	and $F_a(x)\ge1$ for $0\le x<1$. Finally, we have the identity
	\begin{equation}\label{eq:virial-identity}
		\iint_{\mathbb R^2}|t-s|H_n(|t-s|)\rho_\alpha(t)\rho_\alpha(s)\,\mathrm d t \,\mathrm d s=\frac{2}{n\alpha}.	
	\end{equation}

For $t>0$, the Beta-integral calculation in Proposition~\ref{prop:mode-green} remains valid for every positive dimension parameter, since the integrand is integrable near both $s=0$ and $s=1$. We may therefore apply it with dimension parameter $n-2$ and degree $2$, using $b_n(\xi)=a_{n-2,2}(\xi)$.
By \eqref{eq:H-definition}, integrating $g_n$ from zero to $t$ gives \eqref{eq:H-beta}. Euler's integral representation \eqref{eq:hyp-euler} and the quadratic transformation \eqref{eq:quadratic-transformation} give \eqref{eq:H-hyper}. 


	Since
	\begin{equation*}
	F_a(x)=\sum_{j=0}^\infty\frac{(\frac{1}{2})_j}{(a+1)_j}x^j,
	\end{equation*}
	all coefficients are nonnegative and $F_a\ge1$. Substitution of this series into \eqref{eq:F-first-order} proves the identity term by term.

To prove \eqref{eq:virial-identity}, we evaluate the energy \eqref{eq:free-energy} along the mass-preserving dilation $\rho_\lambda(t)=\lambda\rho_\alpha(\lambda t)$.

	A change of variables gives
	\begin{equation*}
\int_\mathbb R\rho_\lambda\log\rho_\lambda\,\mathrm d t
=\log\lambda+\int_\mathbb R\rho_\alpha\log\rho_\alpha\,\mathrm d t,
	\end{equation*}
	and the interaction term in \eqref{eq:free-energy} becomes
	\begin{equation*}
	\frac{C_{n,\alpha}}{2}\iint_{\mathbb R^2}\mathcal K_n\!\left(\frac{t-s}{\lambda}\right)\rho_\alpha(t)\rho_\alpha(s)\,\mathrm d t\,\mathrm d s.
	\end{equation*}

	Since $\rho_\alpha$ is a critical point, we have
	\begin{equation*}
	0=\frac{d\mathcal{F}_{n,\alpha}(\rho_\lambda)}{d\lambda}\Big|_{\lambda=1}
    =1-\frac{C_{n,\alpha}}{2}\iint_{\mathbb R^2}|t-s|\mathcal K_n'(|t-s|)\rho_\alpha(t)\rho_\alpha(s)\,\mathrm d t\,\mathrm d s.
	\end{equation*}
	Then \eqref{eq:virial-identity} follows from the identities $H_n=2\beta_n\mathcal K_n'$ and $C_{n,\alpha}=2n\alpha\beta_n$.

\label{lem:kernel-comparison}
	For every $n\ge3$, $k\ge2$ and $t>0$, we have
	\begin{equation}\label{eq:kernel-comparison}
		1-R_{n,k}(t) <\frac{\lambda_{n,k}}{2(n-2)}\tanh t\,H_n(t).
	\end{equation}

Let $a=\frac{n-2}{2}$, $x=\operatorname{sech}^2t$ and $F_a$ be as in
	Lemma~\ref{lem:H-representations}.  Define
	\begin{equation*}
		\Phi_n(t):=\frac{\tanh t\,H_n(t)}{2(n-2)}
		=\frac{(1-x)F_a(x)}{2(n-2)}.
	\end{equation*}
	In the $x$ variable,
	\begin{equation*}
	\mathcal D_n=4x^2(1-x)\partial_x^2+2x(n-3x)\partial_x.
	\end{equation*}
	Using \eqref{eq:F-first-order} and the fact that $F_a\ge1$, we obtain
	\begin{equation*}
		(\mathcal D_n-2n)\Phi_n+1
		=(1-x)\left[1-\frac{n+x}{n-2}F_a(x)\right]<0.
	\end{equation*}
	Since $k\ge2$, $\lambda_{n,k}-2n=(k-2)(k+n)\ge0$, so
	\begin{equation*}
		(\mathcal D_n-\lambda_{n,k})\Phi_n<-1.
	\end{equation*}

	Set $f=\frac{1-R_{n,k}}{\lambda_{n,k}}$. Then \eqref{eq:R-ODE} implies
	\begin{equation*}
	(\mathcal D_n-\lambda_{n,k})f=-1.
	\end{equation*}

	At $t=0$, $f(0)=\Phi_n(0)=0$; while at $t=\infty$, we have
	\begin{equation*}
	\lim_{t\to\infty}f(t)=\frac1{\lambda_{n,k}}, \qquad	\lim_{t\to\infty}\Phi_n(t)=\frac1{2(n-2)}.
	\end{equation*}
	Therefore, the function $w:=\Phi_n-f$ satisfies
	\begin{equation*}
		w(0)=0,\quad \lim_{t\to\infty}w(t)>0, \quad (\mathcal D_n-\lambda_{n,k})w<0.
	\end{equation*}
	A nonpositive interior minimum would satisfy	$w'=0$, $w''\ge0$ and hence $(\mathcal D_n-\lambda_{n,k})w=w''-\lambda_{n,k}w\ge0$, a contradiction. Thus $f<\Phi_n$, which is
	\eqref{eq:kernel-comparison}.

We now combine the preceding estimates with the monotonicity in $\alpha$ proved in Subsection \ref{sec:transversality}. By Proposition \ref{thm:mu2}, we only need to consider the principal eigenvalue $\mu_1(\alpha,k)$.

		In the regular case $\alpha=1$, the solution is explicitly given by
		\begin{equation}\label{v1 explicit}
		v_1(t)=-\log\cosh t.
		\end{equation}
		In this case $W_1(t)=n!\operatorname{sech}^n t$. Using \eqref{eq:mode-symbol} and \eqref{eq:sech-transform}, we have
		\begin{equation*}
			A_{n,k}(\operatorname{sech}^k t)=\frac{\Gamma(n+k)}{\Gamma(k)}\operatorname{sech}^{n+k} t.
		\end{equation*}
		Hence $W_1^{1/2}\operatorname{sech}^k t$ is a positive principal eigenfunction of $\mathscr K_{1,k}$, with eigenvalue
		\begin{equation*}
			\mu_1(1,k)=\frac{\Gamma(n+1)\Gamma(k)}{\Gamma(n+k)}.
		\end{equation*}
		Thus $\mu_1(1,1)=1$, while $\mu_1(1,k)<1$ for every $k\ge2$. By \eqref{eq:principal-lower-estimate}, $\mu_1(\mathfrak a_{n,k}+\mathfrak b_{n,k},k)>1$.  Continuity therefore yields a crossing and \eqref{eq:mu-al-increasing} makes it unique. The range \eqref{eq:main-range-intro} is given by \eqref{al nk lower} and \eqref{al nk upper}.

		By \eqref{eq:mu-kappa-decreasing}, different modes $k$ yield distinct crossing values $\alpha$. This completes the proof.

Let the spherical decomposition of $h$ be
    \begin{equation*}
        h(t,\omega)=\sum_{k=0}^\infty\sum_\ell h_{k,\ell}(t)Y_{k,\ell}(\omega).
    \end{equation*}
    Then each $h_{k,\ell}$ is bounded and satisfies $L_{\alpha,k}h_{k,\ell}=0$. By Theorem \ref{thm radial}, $h_0=c_0v_\alpha'$ for some $c_0$. For $k\ge 1$, Lemma \ref{lem bdd=spec} implies $h_{k,\ell}\in H^n(\mathbb R)$, so the spectral results in this section apply.

    Since $0<\alpha<\alpha_{n,2}$, from Theorem \ref{thm e value L} we conclude that $h_{k,\ell}=0$ for all $k\ge 2$. For $k=1$, we have $\mu_2(\alpha,1)< 1=\mu_1(1,1)$, and the strict monotonicity in $\alpha$ shows that a kernel occurs only at $\alpha=1$. By \eqref{v1 explicit}, $v_1'(t)=-\tanh{t}$. Since the space of degree-$1$ spherical harmonics $\mathcal{H}_1$ is spanned by coordinate functions $\omega_1,\dots, \omega_n$, we obtain \eqref{h kernel}. The Euclidean statement then follows by a change of variable $t=\log|x|$.

\label{thm:quoted-CR}
	Let $X,Y$ be real Banach spaces, let $U\subset\mathbb R\times X$ be a neighborhood of
	$(\lambda_0,0)$ and let $F\in C^r(U,Y)$ with $r\ge2$ and $F(\lambda,0)=0$.  Put
	$L=D_xF(\lambda_0,0)$.  Assume:
	\begin{enumerate}[label=\textup{(\roman*)}]
		\item $L$ is Fredholm of index zero;
		\item $\operatorname{Ker} L=\operatorname{span}\{\phi_0\}$ and $\operatorname{codim}\operatorname{Ran} L=1$;
		\item $D_{\lambda x}F(\lambda_0,0)\phi_0\notin\operatorname{Ran} L$.
	\end{enumerate}
	Then there are $\varepsilon>0$ and $C^{r-1}$ functions	$s\mapsto\lambda(s)$ and $s\mapsto z(s)$, with	$z(s)$ taking values in a fixed complement of $\operatorname{span}\{\phi_0\}$, such that $\lambda(0)=\lambda_0$, $z(0)=0$, and every nontrivial solution near $(\lambda_0,0)$ is of the form
	\begin{equation*}
		(\lambda(s),\,s\phi_0+s z(s)),
		\qquad |s|<\varepsilon.
	\end{equation*}

\label{prop:main-fredholm}
Assume $n\ge3$, $\alpha>0$ and \eqref{eq:weight-condition} holds.	Then
\begin{equation}\label{eq:linearized-map}
		{L}_\alpha=P_n-W_\alpha:	\mathcal X_\nu^{G,e}\longrightarrow\mathcal Y_\nu^{G,e}
	\end{equation}
	is a bounded Fredholm operator of index zero. 

	For the operator $P_n$, we have 
	\begin{equation}\label{eq:free-kernel}
		\operatorname{Ker}\bigl(P_n:\mathcal X_\nu^{G,e}\to\mathcal Y_\nu^{G,e}\bigr)=\operatorname{span}\{1\},
	\end{equation}
	and
	\begin{equation}\label{eq:free-range}
		\operatorname{Ran}\bigl(P_n:\mathcal X_\nu^{G,e}\to\mathcal Y_\nu^{G,e}\bigr)=\left\{f\in\mathcal Y_\nu^{G,e}: \int_\mathbb R	\int_{\mathbb S^{n-1}}f(t,\omega)\,\mathrm d\omega\,\mathrm d t=0\right\}.
	\end{equation}
	On the nonradial $G$-invariant subspace, $P_n: \Pi_\perp H_\nu^n(\mathcal C)^{G,e}\to \Pi_\perp L_\nu^2(\mathcal C)^{G,e}$ is an isomorphism.

We first determine the kernel and range of $P_n$ by treating radial and nonradial functions separately. We then obtain the Fredholm property and index of $L_\alpha$ by compact perturbation.

We now prove the weighted estimate for the nonradial component.  Let $v$ be smooth and compactly supported in $t$, and suppose that $v_{k,\ell}\neq 0$ for only finitely many pairs $(k,\ell)$. Here,  $v_{k,\ell}$ is the coefficient in (\ref{v spher decom}). For $\sigma=\pm\nu$, exponential conjugation and the Fourier convention give
	\begin{equation}\label{eq:conjugation}
		\widehat{e^{\sigma t}(P_nv)_{k,\ell}}(\xi)
		=a_{n,k}(\xi+i\sigma)\widehat{e^{\sigma t}v_{k,\ell}}(\xi).
	\end{equation}
	Indeed, multiplication by $e^{\sigma t}$ corresponds to shifting the Fourier variable to $\xi+i\sigma$.  Since $1+\lambda_k+\xi^2\sim 1+k^2+\xi^2$ uniformly in $k$, applying Plancherel's theorem, summing in $k$ and $\ell$ and using \eqref{eq:shifted-symbol-estimate} yields
	\begin{equation}\label{Pn H perp}
	C^{-1}\left\lVert v\right\rVert_{H_\nu^{n}}\le	\left\lVert P_n v\right\rVert_{L_\nu^2}\le C\left\lVert v\right\rVert_{H_\nu^{n}}, \quad\text{whenever } \Pi_0v=0
	\end{equation}
for some constant $C>1$.  Smooth functions in $\Pi_\perp H_\nu^n(\mathcal C)^{G,e}$ that are compactly supported in $t$ and whose spherical-harmonic expansions involve only finitely many degrees form a dense subspace. Hence \eqref{Pn H perp} is valid for all $v\in \Pi_\perp H_\nu^n(\mathcal{C})^{G,e}$.

We now prove surjectivity onto
$\Pi_\perp L_\nu^2(\mathcal C)^{G,e}$.  Smooth functions in this space that are compactly supported in $t$ and whose spherical-harmonic expansions involve only finitely many degrees form a dense subspace. Let $f$ be such a function. Expand $f$ in spherical harmonics and define $v_{k,\ell}=G_{n,k}*f_{k,\ell}$. Then we have $\widehat{v_{k,\ell}}(\xi)=\frac{\widehat{f_{k,\ell}}(\xi)}{a_{n,k}(\xi)}$. Defining $v$ by \eqref{v spher decom}, the preceding argument shows that $P_nv=f$ and \eqref{Pn H perp} holds. For a general $f\in \Pi_\perp L_\nu^2(\mathcal{C})^{G,e}$, the same result follows from approximation. Thus, $P_n$ is surjective on the nonradial $G$-invariant subspace. In conclusion, $P_n: \Pi_\perp H_\nu^n(\mathcal C)^{G,e}\to \Pi_\perp L_\nu^2(\mathcal C)^{G,e}$ is an isomorphism.

\medskip

We now prove the solvability criterion and weighted estimate for $-y''=f$.  Since $a_{n,0}(\xi)=\xi^2b_n(\xi)$ has a double zero at zero, we first consider the operatoe $-\partial_t^2$. If $y\in H_\nu^2(\mathbb R)$ and $-y''=f$, the decay of $y'$ gives $\int_\mathbb R f=0$.
Conversely, let $f\in L_\nu^2(\mathbb R)^e$ have zero integral. Cauchy--Schwarz gives $sf(s)\in L^1$ and evenness gives $\int_\mathbb R sf(s)\,\mathrm d s=0$. The absolutely convergent integral
\begin{equation}\label{-y''=f}
 y(t):=-\frac12\int_\mathbb R|t-s|f(s)\,\mathrm d s
\end{equation}
defines an even solution of $-y''=f$ in distributions. Since $f$ is even, for $t\ge0$ and $F(t)=e^{\nu t}f(t)$, we can write
\begin{equation*}
 e^{\nu t}y(t)=-\int_0^\infty r e^{-\nu r}F(t+r)\,\mathrm d r,\qquad
 e^{\nu t}y'(t)=\int_0^\infty e^{-\nu r}F(t+r)\,\mathrm d r.  
\end{equation*}
Young's inequality then implies
\begin{equation*}
    \|e^{\nu t}y\|_{L^2(0,\infty)}+\|e^{\nu t}y'\|_{L^2(0,\infty)}\le C_\nu \|e^{\nu t}f\|_{L^2(0,\infty)}.
\end{equation*}
Together with $-y''=f$ and evenness, this yields
\begin{equation}\label{eq:second-derivative-estimate}
 \left\lVert y\right\rVert_{H_\nu^2(\mathbb R)}\le C\left\lVert f\right\rVert_{L_\nu^2(\mathbb R)}.
\end{equation}

We now prove that $B_n:H_\nu^n(\mathbb R)^e\to H_\nu^2(\mathbb R)^e$ is an isomorphism.  Since $\nu<2$, we have $e^{\pm\nu t}g_n\in L^1(\mathbb R)$.
Exponential conjugation and \eqref{eq:shifted-b-estimate}
therefore give
\[
 \left\lVert B_n\phi\right\rVert_{H_\nu^2}\le C\left\lVert \phi\right\rVert_{H_\nu^n},
 \qquad
 \left\lVert g_n*y\right\rVert_{H_\nu^n}\le C\left\lVert y\right\rVert_{H_\nu^2}.
\]
These operators are inverse Fourier multipliers and preserve evenness. This proves that $B_n:H_\nu^n(\mathbb R)^e\to H_\nu^2(\mathbb R)^e$ is an isomorphism.

We now prove the kernel and range formulas for $A_{n,0}$.  Identify $(c,\phi)\in\mathbb R\times H_\nu^n(\mathbb R)^e$ with $c+\phi$. Since $A_{n,0}(c+\phi)=-(B_n\phi)''$, a kernel element has $B_n\phi$ affine and in $H_\nu^2$, hence $B_n\phi=0$ and $\phi=0$. Thus
\begin{equation}\label{eq:radial-kernel}
 \operatorname{Ker} A_{n,0}=\operatorname{span}\{1\}.
\end{equation}
Every range element has zero integral. Conversely, for an even $f$ with zero integral, take $y$ from \eqref{-y''=f} and $\phi=B_n^{-1}y$. Then $A_{n,0}\phi=f$ and by \eqref{eq:second-derivative-estimate},
\begin{equation*}
    \left\lVert \phi\right\rVert_{H_\nu^n}\le C\left\lVert y\right\rVert_{H_\nu^2}\le C\left\lVert f\right\rVert_{L_\nu^2}.
\end{equation*}
Therefore
\begin{equation}\label{eq:radial-range}
 \operatorname{Ran} A_{n,0}=\left\{f\in L_\nu^2(\mathbb R)^e:\int_\mathbb R f(t)\,\mathrm d t=0\right\}.
\end{equation}
Integration is a nonzero continuous functional on $L_\nu^2(\mathbb R)^e$, so the range is closed with codimension one and $\operatorname{ind} A_{n,0}=0$.  Combining this with the nonradial isomorphism gives \eqref{eq:free-kernel},
\eqref{eq:free-range} and $\operatorname{ind} P_n=0$.

We now prove that multiplication by $W_\alpha$ is compact. The result for $L_{\alpha}$ then follows by compact perturbation. Normality gives $W_\alpha(t)=O(e^{-n\alpha|t|})$. Since $\nu<n\alpha$, $W_\alpha\in L_\nu^2(\mathcal C)$, so $c\mapsto cW_\alpha$ is bounded and finite rank. Choose smooth cutoffs $0\le\chi_R\le1$, equal to one for $|t|\le R$ and zero for $|t|\ge2R$. Rellich's theorem on bounded cylinders makes $\phi\mapsto\chi_RW_\alpha\phi$ compact from $H_\nu^n(\mathcal C)$ to $L_\nu^2(\mathcal C)$ and
\begin{equation*}
 \left\lVert (1-\chi_R)W_\alpha\phi\right\rVert_{L_\nu^2}
 \le \sup_{|t|>R}|W_\alpha(t)|\,\left\lVert \phi\right\rVert_{L_\nu^2}
 \le Ce^{-n\alpha R}\left\lVert \phi\right\rVert_{H_\nu^n}.
 \end{equation*}

Operator-norm convergence and the finite-rank constant part therefore give compactness of multiplication by $W_\alpha$ from $\mathcal X_\nu^{G,e}$ to $\mathcal Y_\nu^{G,e}$. The compact perturbation theorem \cite[Chapter~IV, Theorem~5.26]{Kato1995} now shows that $L_\alpha=P_n-W_\alpha$ is Fredholm with $\operatorname{ind} L_\alpha=\operatorname{ind} P_n=0$. This completes the proof.

\label{coro v al smooth}
	$v_\alpha$ depends smoothly on $\alpha$. To be more precise, we fix $\alpha_0>0$ and $0<\nu<\min\{1,n\alpha_0\}$. Then $0<\nu<\min\{1,n\alpha\}$ for all $\alpha\in I$, a small neighborhood of $\alpha_0$. For $\tau(t)$ defined in \eqref{def tau}, the map
    \begin{equation*}
        \alpha\mapsto v_\alpha+\alpha\tau 
    \end{equation*}
    is smooth from $I$ to $\mathbb R\times H_\nu^n(\mathbb R)^e$

The definition of $\tau$ gives
\begin{equation*}
    A_{n,0}\tau=-2\beta_n\eta,
\end{equation*}
and by \eqref{eq:K-linear-revised}, we see that
\begin{equation*}
	\tau(t)=|t|+O(e^{-2|t|}),\qquad |t|\to\infty.
\end{equation*}

By \eqref{eq:v al infty} and \eqref{int e nv}, the function $h_\alpha:=(n-1)!e^{nv_\alpha}-2\beta_n\alpha\eta$ satisfies
\begin{equation*}
	h_\alpha\in L_\nu^2(\mathbb R)^e, \qquad \int_\mathbb R h_\alpha(t)\,\mathrm d t=0.
\end{equation*}
Equations \eqref{eq:radial-kernel} and \eqref{eq:radial-range} imply that $A_{n,0}$ is an isomorphism from ${H}^n_{\nu}(\mathbb R)^e$ onto the zero-mean subspace of $L^2_\nu(\mathbb R)^e$. Therefore, there exists a unique $\varphi_\alpha\in {H}^n_{\nu}(\mathbb R)^e$ such that
\begin{equation*}
	A_{n,0}\varphi_\alpha=h_\alpha.
\end{equation*}
Consequently,
\begin{equation*}
	A_{n,0}(v_\alpha+\alpha\tau-\varphi_\alpha)=0.
\end{equation*}
The function in parentheses is an even tempered distribution. By Lemma \ref{lem:tempered-radial-kernel}, there is a constant $c_\alpha$ such that
\begin{equation}\label{eq:v-alphadecomposition}
	v_\alpha=-\alpha\tau+c_\alpha+\varphi_\alpha.
\end{equation}


We define the map
\begin{equation*}
	\mathscr{F}: I \times\mathbb R\times H^{n}_\nu(\mathbb R)^e
	\longrightarrow L^2_\nu(\mathbb R)^e
\end{equation*}
by
\begin{equation*}
	\mathscr{F}(\alpha,c,\varphi)=A_{n,0}\varphi+2\beta_n\alpha\eta-(n-1)!e^{n(-\alpha\tau+c+\varphi)}.
\end{equation*}
Then for $v=-\alpha\tau+c+\varphi$, $\mathscr{F}(\alpha,c,\varphi)=0$ is equivalent to the radial equation \eqref{eq:radial-equation}.

Using the embedding $H^n_\nu(\mathbb R)\to L^\infty(\mathbb R)$ and the fact that $e^{-n\alpha\tau},$ together with all of its local $\alpha$-derivatives, belongs to $L^2_\nu(\mathbb R)$, we obtain that $\mathscr{F}$ is smooth in all its arguments. Moreover, its derivative with respect to $(c,\varphi)$ is 
\begin{equation*}
    D_{(c,\varphi)}\mathscr{F}(\alpha,c,\varphi)[d,\psi]=A_{n,0}\psi-n!e^{n(-\alpha\tau+c+\varphi)}(d+\psi),
\end{equation*}
which agrees with $L_{\alpha,0}$ when $v_\alpha=-\alpha\tau+c_\alpha+\varphi_\alpha$. By Proposition~\ref{prop:radial-nondegeneracy}, the kernel of $L_{\alpha,0}$ is spanned by the odd function $v_\alpha'$, so $L_{\alpha,0}(d+\psi)=0$ implies that $d=0$ and $\psi=0$. On the other hand, Proposition \ref{prop:main-fredholm} implies that $L_{\alpha,0}$ is Fredholm of index zero, so it is an isomorphism. Therefore, by the implicit function theorem (see \cite[Theorem~15.1 and Corollary~15.1]{Deimling1985}), the map 
\begin{equation*}
	\alpha \mapsto (c_\alpha, \varphi_\alpha)
\end{equation*}
is smooth into $\mathbb R\times H^{n}_\nu(\mathbb R)^e$. This produces a unique local smooth family
\begin{equation*}
    \tilde{v}_\alpha=-\alpha\tau+\tilde c_\alpha+\tilde\varphi_\alpha.
\end{equation*}
By construction, $\tilde{v}_\alpha$ is an even normal solution of \eqref{eq:radial-equation}. The uniqueness therefore gives $\tilde{v}_\alpha=v_\alpha$. This proves the smooth dependence.

\label{cor:crossing-range}
	Let $\alpha_*=\alpha_{n,k}$ with $k\ge2$. Assume that $\dim\mathcal{H}_k^G=1$. Let $Y_k$ span $\mathcal{H}_k^G$ and let	$\psi_{\alpha_*,k}$ span $\operatorname{Ker} L_{\alpha_*,k}$. Set
	\begin{equation*}
		\Phi_k(t,\omega):=\psi_{\alpha_*,k}(t)Y_k(\omega).
	\end{equation*}
	Then for $L_{\alpha_*}: \mathcal X_\nu^{G,e} \to \mathcal Y_\nu^{G,e}$, we have
	\begin{equation}\label{eq:crossing-kernel}
		\operatorname{Ker} L_{\alpha_*}=\operatorname{span}\{\Phi_k\},
	\end{equation}
	and
	\begin{equation}\label{eq:crossing-range}
		\operatorname{Ran} L_{\alpha_*}=\left\{f\in\mathcal Y_\nu^{G,e}:\int_\mathcal C f(t,\omega)\Phi_k(t,\omega)\,\mathrm d t\,\mathrm d\omega=0\right\}.
	\end{equation}

We first show that the eigenfunction $\psi_{\alpha_*,k}$ is in the desired weighted space. In fact, since $W_\alpha\psi_{\alpha_*,k}\in L^2_\nu(\mathbb R)$, the equation $\psi_{\alpha_*,k}=A_{n,k}^{-1}(W_\alpha \psi_{\alpha_*,k})$ and the weighted inverse estimate in the proof of Proposition \ref{prop:main-fredholm} show that $\psi_{\alpha_*,k}\in H^n_{\nu}(\mathbb R)$ for $\nu<\min\{1,n\alpha_*\}$. Then \eqref{eq:crossing-kernel} follows directly from Theorem \ref{thm e value L}. Now let $u=c+\phi\in \mathcal X_\nu^{G,e}$. Since $\Phi_k$ is orthogonal to constants, by self-adjointness, we have
    \begin{equation*}
        \int_{\mathcal C}L_{\alpha_*}(c+\phi)\Phi_k=\int_{\mathcal C}L_{\alpha_*}(\Phi_k)\phi=0.
    \end{equation*}
Consequently,
\begin{equation*}
    \operatorname{Ran} L_{\alpha_*}\subseteq\left\{f\in\mathcal Y_\nu^{G,e}:\int_\mathcal C f(t,\omega)\Phi_k(t,\omega)\,\mathrm d t\,\mathrm d\omega=0\right\}.
\end{equation*}
Since $L_{\alpha_*}$ has index zero and $\operatorname{Ker} L_{\alpha_*}$ is one-dimensional, $\operatorname{Ran} L_{\alpha_*}$ has codimension $1$. Then \eqref{eq:crossing-range} follows.

\label{thm:cumulative-positivity}

For $t\ge0$, define
\begin{equation*}
 M(t):=\int_0^tW_\alpha(s)q_\alpha(s)\,\mathrm d s.
\end{equation*}  
Then $M(t)>0$ for all $t>0$.

The monotonicity is stated for every real $\kappa>0$. Here we only prove it for positive integer $k$, and the same argument works for all $\kappa>0$.
Let $\psi_{\alpha,k}>0$ be the even principal eigenfunction defined by \eqref{eq:generalized-eigenpair}. Then by Proposition \ref{thm:mu2}, $\partial_t\psi_{\alpha,k}(t)<0$ for $t>0$.

An integration by parts, together with
Lemma~\ref{thm:cumulative-positivity} and
$\partial_t(\psi_{\alpha,k}^2)<0$ on $(0,\infty)$, gives
\begin{equation*}
 \int_\mathbb R W_\alpha q_\alpha\psi_{\alpha,k}^2\,\mathrm d t
 =-2\int_0^\infty M(t)(\psi_{\alpha,k}^2)'(t)\,\mathrm d t>0.
\end{equation*}
The boundary terms vanish because $M(0)=0$, $M$ is bounded at infinity and
$\psi_{\alpha,k}$ decays exponentially.

Corollary \ref{coro v al smooth} proves smooth dependence of the radial profile $v_\alpha$ on $\alpha$ in a weighted space. Moreover, locally in $\alpha$, the exponential decay of $W_\alpha$ implies the differentiability of the integral kernel $\eqref{int kernel K}$. Hence the operator $\mathscr{K}_{\alpha,k}$ depends smoothly on $\alpha$ in operator norm. By the simplicity of the principal Birman--Schwinger eigenvalue and perturbation theory (see \cite[Chapter VII]{Kato1995}), the simple eigenvalue has a locally smooth normalized eigenfunction.

Now we can differentiate the generalized eigenvalue equation 
$A_{n,k}\psi_{\alpha,k}=\tau_{\alpha,k} W_\alpha\psi_{\alpha,k}$ with respect to $\alpha$  to obtain
\begin{equation*}
 \partial_\alpha\tau_{\alpha,k}
 =-n\tau_{\alpha,k}
 \frac{\int_\mathbb R W_\alpha q_\alpha\psi_{\alpha,k}^2\,\mathrm d t}
 {\int_\mathbb R W_\alpha\psi_{\alpha,k}^2\,\mathrm d t}<0.
\end{equation*}
Since $\tau_{\alpha,k}=\frac{1}{\mu_1({\alpha,k})}$, this proves \eqref{eq:mu-al-increasing}.

\label{prop:transversality}
For $\alpha_*=\alpha_{n,k}$, we have
\begin{equation*}
 \partial_\alpha L_{\alpha,k}\big|_{\alpha=\alpha_*}\psi_{\alpha_*,k}
 =-nW_{\alpha_*}q_{\alpha_*}\psi_{\alpha_*,k} \notin\operatorname{Ran} L_{\alpha_*,k}.
\end{equation*}

Let $G=O(n-1)$ be the subgroup that fixes the last coordinate axis.  For each degree $j$, the $G$-invariant spherical-harmonic space $\mathcal{H}^G_j$ is one-dimensional, generated by
\begin{equation*}
 Y_j(\omega)=c_j\,C_j^{\frac{n-2}{2}}(\omega_n),
\end{equation*}
where $C_j^{\frac{n-2}{2}}$ is the Gegenbauer polynomial and $c_j$ is a nonzero normalizing constant. Thus by \eqref{eq:kG}, $k_G=1$.  For $\lambda>0$, the Gegenbauer polynomials $C_j^\lambda$ are defined by the generating function \cite[Eq.~(18.12.4)]{DLMF}
\[
 (1-2z\rho+\rho^2)^{-\lambda}
 =\sum_{j=0}^\infty C_j^\lambda(z)\rho^j,
 \qquad z\in[-1,1],\quad |\rho|<1.
\]


Fix $k\ge2$, set $\alpha_*=\alpha_{n,k}$ and choose
\begin{equation*}
 0<\nu<\min\{1,n\alpha_*\}.
\end{equation*}
Let $\mathcal X_\nu^{G,e}$ and $\mathcal Y_\nu^{G,e}$ be defined in \eqref{eq:X-Y}. Define the map
\begin{equation*}
 \mathcal F(\alpha,w):=P_nw-(n-1)!e^{nv_\alpha}(e^{nw}-1).
\end{equation*}
Let $I$ be a neighborhood of $\alpha_*$ such that $\nu<n\alpha$ for all $\alpha\in I$. Then
\begin{equation*}
 \mathcal F:I\times\mathcal X_\nu^{G,e} \longrightarrow \mathcal Y_\nu^{G,e}
\end{equation*}
is smooth near $(\alpha_*,0)$ and
\begin{equation*}
 \mathcal F(\alpha,0)=0, \qquad D_w\mathcal F(\alpha,0)=P_n-W_\alpha= L_\alpha.
\end{equation*}

At $\alpha_*=\alpha_{n,k}$, the centered radial mode is invertible.  Since $\dim\mathcal H_k^G=1$, Corollary~\ref{cor:crossing-range}
shows that
\[
 \operatorname{Ker}\bigl(L_{\alpha_*}:\mathcal X_\nu^{G,e}\to\mathcal Y_\nu^{G,e}\bigr)
 =\operatorname{span}\{\psi_{\alpha_*,k}(t)Y_k(\omega)\}.
\]
The Fredholm property of $L_\alpha$ is proved in Proposition \ref{prop:main-fredholm} and Proposition \ref{prop:transversality} gives the transversality condition.

In summary, all hypotheses of Theorem \ref{thm:quoted-CR} are satisfied. As a result, a local branch of $O(n-1)$-axisymmetric, nonradial solutions bifurcates from $v_{\alpha_*}$ for $\alpha_*=\alpha_{n,k}$. More precisely, there are $\varepsilon_0>0$ and smooth functions $s\mapsto(\alpha(s),w(s))$ for $|s|<\varepsilon_0$ such that
\begin{equation*}
 \alpha(0)=\alpha_{*}, \qquad w(0)=0, \qquad w(s)=s\psi_{\alpha_*,k}(t)Y_k(\omega)+o(s) \text{ in } \mathcal X_\nu^{G,e},
\end{equation*}
and $V_s(t,\omega)=v_{\alpha(s)}(t)+w(s;t,\omega)$ solves \eqref{eq:cylinder-equation}.

Returning to Euclidean variables, we set
\[
 u_s(r,\omega)
 =V_s(\log r,\omega)-\alpha(s)\log r.
\]
Since $w(s)\in\mathcal X_\nu^{G,e}$, we write
\[
 w(s)=c_s+\varphi_s,\qquad
 \varphi_s\in H_\nu^n(\mathcal C)^{G,e}.
\]
Weighted Sobolev embedding gives
$\varphi_s(t,\omega)=O(e^{-\nu|t|})$ uniformly in $\omega$. Hence $u_s$ extends continuously to the origin,
\[
 u_s(x)=-2\alpha(s)\log|x|+O(1)
 \quad\text{as }|x|\to\infty,
\]
and
\begin{equation*}
\int_{\mathbb R^n}|x|^{n(\alpha(s)-1)}e^{nu_s}\,\mathrm d x=\int_\mathcal C e^{n(v_{\alpha(s)}+w(s))}\,\mathrm d t\,\mathrm d\omega<\infty.    
\end{equation*}

The equation holds away from the origin by conformal covariance. Lemma~\ref{lem:removability-normality} therefore shows that $u_s$ is a normal solution on $\mathbb R^n$. This completes the proof.

\label{rig:prop:compactness}
Let $\gamma_j\downarrow0$ and let $u_j$ be normal solutions normalized by
\eqref{rig:eq:median}.  Then, after passing to a subsequence,
\begin{equation*}
 u_j\longrightarrow U \quad\text{in }C^0_{\mathrm{loc}}(\mathbb R^n)
 \text{ and in }C^\ell_{\mathrm{loc}}(\mathbb R^n\setminus\{0\})
 \text{ for every }\ell\geq0,
\end{equation*}
where
\begin{equation}\label{rig:eq:standard-bubble}
 U(x)=\log\frac{2}{1+|x|^2}.
\end{equation}

\label{lem: fj L2 uniform}
Suppose that, for a fixed ball $B_{2r}(q)$,
\begin{equation*}
    m_j:=\int_{B_{2r}(q)}f_j\,\mathrm d x\le \frac{|\mathbb S^n|}{16}.
\end{equation*}
Then $\|f_j\|_{L^2(B_{r}(q))}\le C$ for some $C$ that depends only on $q$ and $r$ and is uniform in $j$.

For $x\in B_r(q)$, the kernel $K(x,y)$ is uniformly bounded for $y\notin B_{2r}(q)$. For $y\in B_{2r}(q)$, we have $K(x,y)\le C+\log^+\frac{1}{|x-y|}$. Thus, by \eqref{def Hj} and \eqref{f_j rep new}, we have
    \begin{equation*}
        f_j(x)^2\le C\exp\Big\{\frac{4n}{|\mathbb S^n|}\int_{B_{2r}(q)} \log^+\frac{1}{|x-y|} f_j(y)\,\mathrm d y\Big\}
    \end{equation*}
    Applying Jensen's inequality to the probability measure $\frac{\chi_{B_{2r}(q)}}{m_j}f_j(y)\,\mathrm d y$, we obtain
    \begin{equation*}
        f_j(x)^2\le \frac{C}{m_j}\int_{B_{2r}(q)} \max\{1,{|x-y|}^{-\frac{4n}{|\mathbb S^n|}m_j} \}f_j(y)\,\mathrm d y.
    \end{equation*}
    Since $\frac{4n}{|\mathbb S^n|}m_j\le \frac{n}4<n$,  integrating in $x\in B_r(q)$ gives
    \begin{equation*}
           \int_{B_{r}(q)}f_j(x)^2\,\mathrm d x\le \frac{C}{m_j}\int_{B_{2r}(q)} \int_{B_r(q)}\max\{1,{|x-y|}^{-\frac{4n}{|\mathbb S^n|}m_j} \}\,\mathrm d xf_j(y)\,\mathrm d y\le C.
    \end{equation*}
    This proves the lemma.

\label{rig:lem:blowup-profile}
Let $\{u_j\}$ be a sequence in Proposition~\ref{rig:prop:compactness}. Assume that $\max_{\mathbb R^n}u_j\to\infty$.  Let $x_j$ be a maximum point and let $r_j>0$ be the unique solution of
\begin{equation}\label{rig:eq:implicit-scale}
 r_j e^{u_j(x_j)}(|x_j|+r_j)^{\gamma_j}=1.
\end{equation}
Then $r_j\to0$ and up to a subsequence,
\begin{equation*}
\eta_j(z):=u_j(x_j+r_jz)-u_j(x_j)
\end{equation*}
converges in $C_{loc}(\mathbb R^n)$ to a normal solution of
\begin{equation}\label{rig:eq:limit-equation}
 (-\Delta)^{n/2}\eta=(n-1)!e^{n\eta}\quad\text{in }\mathbb R^n
\end{equation}
with
\begin{equation}\label{rig:eq:bubble-mass}
 \int_{\mathbb R^n}e^{n\eta}\,\mathrm d z=|\mathbb S^n|.
\end{equation}

The left-hand side of \eqref{rig:eq:implicit-scale} is strictly increasing from zero to infinity, so $r_j$ exists uniquely. Moreover, we get $r_j^{1+\gamma_j}\le e^{-u_j(x_j)}$ and hence $r_j\to0$.
The rescaled density is
\begin{equation}\label{fj til}
 \widetilde f_j(z):=K_j(z)e^{n\eta_j(z)}\text{ with } K_j(z)= \left(\frac{|x_j+r_jz|}{|x_j|+r_j}\right)^{n\gamma_j}.
\end{equation}
Then we have
 \begin{equation*}
     \int_{\mathbb R^n}\widetilde f_j\,\mathrm d z=\int_{\mathbb R^n}f_j\,\mathrm d x\le C.
 \end{equation*}

We can assume $\gamma_j\le1$ after discarding finitely many terms.  For $R\ge1$ and $|z|\le R$, we have $K_j(z)\le R^n$.
Passing to a subsequence, $\frac{x_j}{r_j}$ either converges or tends to infinity and $K_j\to1$ almost everywhere.

Subtracting the normal representations of $u_j$ at $x_j+r_jz$ and $x_j$ gives
\begin{equation}\label{eta rep}
 \eta_j(z)=\frac{2}{|\mathbb S^n|}\int_{\mathbb R^n}\log\frac{|\zeta|}{|z-\zeta|}\widetilde f_j(\zeta)\,\mathrm d\zeta.   
\end{equation}


Since $\eta_j\le0$, $\widetilde f_j$ is uniformly bounded on every fixed ball. Fix $R\ge1$. Since $\widetilde f_j$ is locally bounded and belongs to $L^1(\mathbb R^n)$, we differentiate the logarithmic potential in the weak sense (see \cite[Lemma~2.3(i)]{Hyder2019}). This gives
\begin{equation*}
 \nabla\eta_j(z)=-\frac{2}{|\mathbb S^n|} \int_{\mathbb R^n}\frac{z-\zeta}{|z-\zeta|^2}\widetilde f_j(\zeta)\,\mathrm d\zeta.    
\end{equation*}

For $z\in B_R$, the integral over $B_{2R}$ satisfies
 \begin{equation*}
 \int_{B_{2R}}\frac{\widetilde f_j(\zeta)}{|z-\zeta|}\,\mathrm d\zeta
 \le \|\widetilde f_j\|_{L^\infty(B_{2R})}\int_{B_{3R}}\frac{\,\mathrm d y}{|y|}
\le C_nR^{n-1}\|\widetilde f_j\|_{L^\infty(B_{2R})}.
 \end{equation*}
On the complement, $|z-\zeta|\ge|\zeta|-R\ge R$, so
\begin{equation*}
 \int_{\mathbb R^n\setminus B_{2R}}\frac{\widetilde f_j(\zeta)}{|z-\zeta|}\,\mathrm d\zeta
 \le R^{-1}\|\widetilde f_j\|_{L^1(\mathbb R^n)}.
\end{equation*}
Consequently,
\begin{equation*}
 \|\nabla\eta_j\|_{L^\infty(B_R)}
 \le C_n\left(R^{n-1}\|\widetilde f_j\|_{L^\infty(B_{2R})}+R^{-1}\|\widetilde f_j\|_{L^1(\mathbb R^n)}\right)
 \le C_R,
\end{equation*}
where $C_R$ is independent of $j$.
Together with $\eta_j(0)=0$, this yields local $W^{1,\infty}$ bounds. Thus, up to a subsequence, $\eta_j\to\eta$ in $C^0_{\mathrm{loc}}(\mathbb R^n)$ and $\widetilde f_j\to e^{n\eta}$ in $L^1_{\mathrm{loc}}(\mathbb R^n)$. Fatou's lemma gives $\int_{\mathbb R^n}e^{n\eta}\,\mathrm d z<\infty$.

We now pass to the limit in \eqref{eta rep}. For $|\zeta|>R>2|z|$, we have
\begin{equation*}
 \left|\log\frac{|\zeta|}{|z-\zeta|}\right|\le C\frac{|z|}{|\zeta|}.   
\end{equation*}
On fixed balls, we use the uniform convergence obtained above. Therefore, letting first $j\to\infty$ and then $R\to\infty$ in \eqref{eta rep} gives
\begin{equation*}
 \eta(z)=\frac{2}{|\mathbb S^n|}\int_{\mathbb R^n}\log\frac{|y|}{|z-y|}e^{n\eta(y)}\,\mathrm d y
 =c_\eta+\frac{2}{|\mathbb S^n|}\int_{\mathbb R^n}\log\frac{1+|y|}{|z-y|}e^{n\eta(y)}\,\mathrm d y.
\end{equation*}
Here $c_\eta$ is finite because $\eta\le0$ and $e^{n\eta}\in L^1$. This representation gives \eqref{rig:eq:limit-equation} and normality. Local regularity gives smoothness. The classifications \cite[Theorem~2]{Martinazzi2009} in even dimensions and \cite[Theorem~1.3]{Hyder2019} in odd dimensions now show that $\eta$ is a standard bubble. In particular, \eqref{rig:eq:bubble-mass} holds.

Suppose for contradiction that $\max\limits_{\mathbb R^n}u_j\to\infty$. We  take the maximum points $x_j$ and scales $r_j$ from Lemma~\ref{rig:lem:blowup-profile}. Let $\eta$ be the limit function in Lemma~\ref{rig:lem:blowup-profile}. After passing to a subsequence, $x_j\to x_*\in\mathbb R^n\cup\{\infty\}$.
For every $\varepsilon>0$, we can choose $R$ such that
\begin{equation*}
     \int_{B_R}e^{n\eta}\,\mathrm d z>|\mathbb S^n|-\varepsilon.
\end{equation*}
For $f_j=|x|^{n\gamma_j}e^{nu_j}$, the local convergence of the rescaled densities \eqref{fj til} gives
\begin{equation*}
 \liminf_{j\to\infty}\int_{B_{Rr_j}(x_j)}f_j(x)\,\mathrm d x
 \ge\int_{B_R}e^{n\eta}\,\mathrm d z
 >|\mathbb S^n|-\varepsilon.
\end{equation*}
Since $r_j\to0$ and the total mass of $f_j\,\mathrm d x$ is $\alpha_j|\mathbb S^n| \to |\mathbb S^n|$, the mass outside these shrinking balls tends to zero as $\varepsilon\downarrow0$. Consequently,
\begin{equation}\label{conver fj dx}
    f_j\,\mathrm d x\rightharpoonup|\mathbb S^n|\delta_{x_*}
\end{equation}
The median normalization \eqref{rig:eq:median} rules out both $x_*=0$ and $x_*=\infty$, because otherwise the mass of $B_1$ would then tend respectively to the full mass or to zero.  Hence $x_*\in\mathbb R^n\setminus\{0\}$.

Since $x_*\neq 0$, we can choose $r_0>0$ such that $x_*\notin B_{2r_0}(0)$. Then by concentration at $x_*$, we can apply Lemma \ref{lem: fj L2 uniform} to obtain $\sup_j\|f_j\|_{L^2(B_{r_0}(0))}\le C_{r_0}$. Hence, for $0<\delta<r_0$, the Cauchy--Schwarz inequality implies
\begin{equation*}
     \int_{|x|<\delta}|x|^{-1}f_j(x)\,\mathrm d x\le C_{r_0}(\int_{|x|<\delta}|x|^{-2}\,\mathrm d x)^{\frac{1}{2}}\le C_{r_0}'\delta^{\frac{n-2}{2}}.
\end{equation*}
At infinity, we have the uniform bound
\begin{equation*}
   \int_{|x|>R}|x|^{-1}f_j(x)\,\mathrm d x\le CR^{-1}.
\end{equation*}
Therefore by \eqref{conver fj dx}, we obtain
\begin{equation*}
     \int_{\mathbb R^n}\frac{x}{|x|^2} f_j(x)\,\mathrm d x\longrightarrow |\mathbb S^n|\frac{x_*}{|x_*|^2}
\end{equation*}
because there is no loss of mass at $0$ or infinity. Passing to the limit in \eqref{rig:eq:inverse-moment} therefore gives $0=|\mathbb S^n|x_*$, contradicting \(x_*\ne0\). Hence concentration is impossible, and the lemma is proved.

By Lemma~\ref{rig:lem:no-concentration}, the functions $u_j$ are uniformly bounded above. Hence $f_j$ is uniformly bounded on every fixed ball. Using \eqref{grad u rep f} and splitting the integral into $|x-y|<1$ and its complement, we obtain, for every $R\ge1$,
\begin{equation*}
 \|\nabla u_j\|_{L^\infty(B_R)}
 \le \frac{2}{|\mathbb S^n|}\left(\|f_j\|_{L^\infty(B_{R+1})}\int_{B_1}|z|^{-1}\,\mathrm d z+\|f_j\|_{L^1(\mathbb R^n)}\right)
 \le C_R.
\end{equation*}
On the other hand, since $\gamma_j>0$, the median normalization
\eqref{rig:eq:median} gives
\begin{equation*}
 \frac{|\mathbb S^n|}{2}\le \int_{B_1}f_j\,\mathrm d x\le |B_1|\exp\left(n\sup_{B_1}u_j\right).\end{equation*}
Thus $\sup_{B_1}u_j$ is uniformly bounded below. Together with
the gradient estimate and the uniform upper bound, this yields
\begin{equation*}
 \sup_j\|u_j\|_{W^{1,\infty}(B_R)}<\infty \qquad\text{for every }R\ge1.   
\end{equation*}
The Arzel\`a--Ascoli theorem therefore
gives, after passing to a subsequence,
\begin{equation*}
 u_j\longrightarrow u_0\quad\text{in }C^0_{\mathrm{loc}}(\mathbb R^n).    
\end{equation*}

Let $\Omega'\Subset\Omega\Subset\mathbb R^n\setminus\{0\}$ and $1<p<\infty$. The local potential estimates used in the proof of \cite[Theorem~2.1]{HMM2021}, applied to the normal
representation, give
\[
 \|u_j\|_{W^{n,p}(\Omega')}
 \le C\left(
 \|f_j\|_{L^p(\Omega)}
 +\|f_j\|_{L^1(\mathbb R^n)}
 +\|u_j\|_{L^\infty(\Omega)}
 \right)\le C,
\]
where $C$ is independent of $j$. Since the weights $|x|^{n\gamma_j}$ have uniformly bounded derivatives of every order on $\Omega$, the regularity iteration in the same proof yields
\begin{equation*}
 \sup_j\|u_j\|_{W^{m,p}(\Omega')}<\infty
 \qquad\text{for every integer }m\ge1.   
\end{equation*}
Compact Sobolev embeddings therefore give, up to a subsequence,
\[
 u_j\longrightarrow u_0
 \quad\text{in }C^\ell_{\mathrm{loc}}(\mathbb R^n\setminus\{0\})
 \qquad\text{for every }\ell\ge0.
\]

We next control the mass at infinity. By the uniform bound of $u_j$ in $B_1$ and the Kelvin symmetry, we obtain
\begin{equation*}
     f_j(x)\leq C|x|^{-2n-n\gamma_j}, \qquad |x|>1
\end{equation*}
for some constant $C$ independent of $j$. Consequently,
\begin{equation}\label{int fj uniform}
 \sup_j\int_{|x|>R}(1+|x|)f_j(x)\,\mathrm d x\leq CR^{-(n-1)}.   
\end{equation}
Thus both the masses and the first moments are uniformly integrable. Since \(\gamma_j\to0\) and \(u_j\to u_0\) locally uniformly,
\begin{equation*}
 f_j=|x|^{n\gamma_j}e^{nu_j}
 \longrightarrow e^{nu_0}
 \quad\text{in }L^1_{\mathrm{loc}}(\mathbb R^n).    
\end{equation*}
Combining this local convergence with \eqref{int fj uniform},
we obtain
\begin{equation*}
     \int_{\mathbb R^n}e^{nu_0}\,\mathrm d x=\lim_{j\to\infty}\int_{\mathbb R^n}f_j\,\mathrm d x
 =|\mathbb S^n|.
\end{equation*}

It remains to verify normality. Fix \(x_0\in\mathbb R^n\). Subtracting the normal representations at \(x\) and \(x_0\) gives
\begin{equation}\label{uj rep x x0}
 u_j(x)-u_j(x_0)=\frac{2}{|\mathbb S^n|}\int_{\mathbb R^n}\log\frac{|x_0-y|}{|x-y|}f_j(y)\,\mathrm d y.   
\end{equation}
On each fixed ball, we pass to the limit by local convergence. On its complement,
\begin{equation*}
     \left|\log\frac{|x_0-y|}{|x-y|}\right|\leq\frac{C_{x,x_0}}{|y|}
\end{equation*}
for large $|y|$, so the uniform mass bound controls the integral outside fixed balls. Therefore, we can pass to the limit in \eqref{uj rep x x0} to obtain
\begin{equation*}
    u_0(x)-u_0(x_0)=\frac{2}{|\mathbb S^n|}\int_{\mathbb R^n}\log\frac{|x_0-y|}{|x-y|}e^{nu_0(y)}\,\mathrm d y.
\end{equation*}
Rearranging this identity yields
\begin{equation*}
 u_0(x)=c_0+\frac{2}{|\mathbb S^n|}\int_{\mathbb R^n}\log\frac{1+|y|}{|x-y|}e^{nu_0(y)}\,\mathrm d y   
\end{equation*}
for some $c_0\in\mathbb R$. The fundamental-solution identity
\begin{equation*}
 (-\Delta)^{n/2}\log\frac1{|x|}=\frac{(n-1)!|\mathbb S^n|}{2}\delta_0    
\end{equation*}
therefore gives
\begin{equation*}
    (-\Delta)^{n/2}u_0=(n-1)!e^{nu_0} \quad\text{in }\mathcal D'(\mathbb R^n).
\end{equation*}
Thus $u_0$ is a normal solution of the unweighted equation. The classifications \cite[Theorem~2]{Martinazzi2009} in even dimensions and \cite[Theorem~1.3]{Hyder2019} in odd dimensions now give
\begin{equation*}
 u_0(x)=\log\frac{2\lambda}{1+\lambda^2|x-\xi|^2}   
\end{equation*} 
for some $\lambda>0$ and $\xi\in\mathbb R^n$ . By the uniform integrability \eqref{int fj uniform} and
Corollary \ref{coro:translation-identity},
\begin{equation*}
0=\lim_{j\to\infty}\int_{\mathbb R^n}x f_j(x)\,\mathrm d x=\int_{\mathbb R^n}x e^{nu_0(x)}\,\mathrm d x=|\mathbb S^n|\xi,    
\end{equation*}
so \(\xi=0\). Finally, passing to the limit in \eqref{rig:eq:median} and
changing variables $y=\lambda x$ give
\begin{equation*}
    \int_{B_\lambda}\left(\frac{2}{1+|y|^2}\right)^n\,\mathrm d y=\int_{B_1}e^{nu_0(x)}\,\mathrm d x
 =\frac{|\mathbb S^n|}{2}.
\end{equation*}
The left-hand side is strictly increasing in $\lambda$ and equals $\frac{|\mathbb S^n|}{2}$ at $\lambda=1$. Therefore $\lambda=1$. Hence
\begin{equation*}
 u_0(x)=\log\frac{2}{1+|x|^2}=U(x)    
\end{equation*}

By Theorem \ref{thm:kelvin}, we know that every normal solution is Kelvin symmetric. Let $u_\gamma^{\text{rad}}$ be the unique radial normal solution such that it is Kelvin symmetric with respect to $B_1$. 
We argue by contradiction. If the theorem were false, we could choose $\gamma_j\downarrow0$ and a normal solution $u_j$ of equation \eqref{eq:euclidean} with parameter $\gamma_j$, which is different from $u_j^{\text{rad}}:=u_{\gamma_j}^{\text{rad}}$ and also Kelvin symmetric with respect to $B_1$. By \eqref{rig:eq:median}, the Kelvin symmetry is equivalent to
\begin{equation*}
	\int_{B_1}(n-1)!|x|^{n\gamma_j}e^{nu_j^{\text{rad}}}\,dx=
	\int_{B_1}(n-1)!|x|^{n\gamma_j}e^{nu_j}\,dx=\frac{(n-1)!(1+\gamma_j)}{2}|\mathbb S^n|.
\end{equation*}

By Proposition \ref{rig:prop:compactness}, we have
\begin{equation}\label{uj conver U}
 u_j, u_j^{\text{rad}}\longrightarrow U=\log\frac{2}{1+|x|^2} \quad\text{in }C^0_{\mathrm{loc}}(\mathbb R^n)
\end{equation}


Set
\begin{equation*}
h_j:=\frac{u_{j}^{\text{rad}}-u_{j}}{\|u_{j}^{\text{rad}}-u_{j}\|_{L^\infty(\mathbb R^n)}}.
\end{equation*}
Then
\begin{equation}\label{eq:maximum}
h_j(\frac{x}{|x|^2})=h_j(x),\qquad
\|h_j\|_{L^\infty(\mathbb R^n)}=\max_{\overline B_1}|h_j|=1.
\end{equation}
We are going to show $h\equiv 0$ to obtain a contradiction.

Subtracting the equations of $u_j$ and $u_j^{\text{rad}}$ yields
\begin{equation*}\label{eq:linear}
(-\Delta)^{n/2}h_j=a_jh_j,\qquad
a_j(x)=n!|x|^{n\gamma_j}\int_0^1 e^{n((1-s)u_{j}^{\text{rad}}(x)+su_{j}(x))}\,ds.
\end{equation*}
For every fixed $R$,  \eqref{uj conver U} gives
\begin{equation}\label{eq:coeff}
0\le a_j\le C_R\quad\hbox{on }B_R,\qquad
a_j\longrightarrow n!e^{nU}\quad\hbox{in }L^p(B_R)
\quad(1\le p<\infty).
\end{equation}


There is also a uniform global $L^1$ bound requiring only the mass identity: 
\begin{equation}\label{eq:L1}
\int_{\mathbb R^n}a_j\,dx\le\frac{n!}{2}\int_{\mathbb R^n}|x|^{n\gamma_j}
\bigl(e^{nu_{j}^{\text{rad}}}+e^{nu_{j}}\bigr)\,dx=n!(1+\gamma_j)|\mathbb S^n|\le C.
\end{equation}

Subtracting the two normal representations of $u_j$ and $u_j^{\text{rad}}$ gives
\begin{equation}\label{eq:repr}
h_j(x)-h_j(0)=-\frac{2}{(n-1)!|\mathbb S^n|}\int_{\mathbb R^n}\log\frac{|x-y|}{|y|}\,a_j(y)h_j(y)\,dy.
\end{equation}
Hence
\begin{equation}\label{grad hj}
\nabla h_j(x)=-\frac{2}{(n-1)!|\mathbb S^n|}\int_{\mathbb R^n}\frac{x-y}{|x-y|^2}\,a_j(y)h_j(y)\,dy.
\end{equation}

 For $x\in B_R$, we split the integral into $|x-y|<1$ and its complement. Differentiate \eqref{grad hj} once more, by \eqref{eq:coeff} and \eqref{eq:L1}, we obtain
\begin{equation*}
	\begin{aligned}
		|\nabla h_j(x)|+|D^2h_j(x)|\le &C\int_{|x-y|<1}
		\frac{1}{|x-y|^2}\,a_j(y)|h_j(y)|\,dy
		+C\int_{|x-y|\geq 1}
		\frac{1}{|x-y|}\,a_j(y)|h_j(y)|\,dy\\
		\le& C_R\int_{|z|<1}
		\bigl(|z|^{-2}\bigr)\,dz+C\int_{\mathbb R^n}a_j\,dy\\
		\le &C_R.
	\end{aligned}
\end{equation*}
Here $D^2h_j$ is first understood in the weak sense. Thus, by the Arzel\`a--Ascoli theorem, after passing to a subsequence, we have
\begin{equation}\label{eq:convergence}
h_j\longrightarrow h\quad\hbox{in }C^1_{\mathrm{loc}}(\mathbb R^n).
\end{equation}
In particular, convergence is uniform on $\overline B_1$. Equation \eqref{eq:maximum} therefore gives
\begin{equation}\label{max h=1}
\max_{\overline B_1}|h|=1,\qquad \|h\|_{L^\infty(\mathbb R^n)}=1.
\end{equation}

Now we pass to the limit in \eqref{eq:repr}. For fixed $x$ and $R>2|x|+1$, we have
\begin{equation*}
\left|\log\frac{|x-y|}{|y|}\right|\le\frac{C_x}{|y|}, \quad |y|>R,
\end{equation*}
so by \eqref{eq:L1}, 
\begin{equation*}
	\int_{|y|>R}\left|\log\frac{|x-y|}{|y|}\right|a_j(y)|h_j(y)|\,dy\le\frac{C_x}{R}.
\end{equation*}
 On bounded sets, we have the convergence \eqref{eq:coeff} and \eqref{eq:convergence}. Consequently,
\begin{equation}\label{eq:limitintegral}
h(x)-h(0)=-\frac{2}{(n-1)!|\mathbb S^n|}\int_{\mathbb R^n}\log\frac{|x-y|}{|y|}\,n!e^{nU(y)}h(y)\,dy.
\end{equation}


We observe that \eqref{eq:limitintegral} is exactly the integral form of the linearized equation at $U$. In other words,
\begin{equation*}
	(-\Delta)^{n/2}h=n!e^{nU}h\quad\hbox{in }\mathbb R^n.
\end{equation*}
By Corollary \ref{coro:nondegen}, the nondegeneracy of $U$ implies that $h=\sum_{i=0}^n c_iZ_i$ for some $c_i\in\mathbb R$, where $Z_0,\dots, Z_n$ are defined by \eqref{eq:kernel}.


Since $\nabla u_j(0)=\nabla u_j^{\text{rad}}(0)=0$ for all $j$, we have  $\nabla h_j(0)=0$. By \eqref{eq:convergence}, $\nabla h(0)=0$. Since
\begin{equation*}
\nabla Z_0(0)=0,\quad \partial_k Z_i(0)=2\delta_{ik}, \qquad i,k=1,\dots,n,
\end{equation*}
we get $c_1=\dots=c_n=0$.

 For every $x\ne0$, equation \eqref{eq:maximum} passes to the limit and gives $h(\frac{x}{|x|^2})=h(x)$. Since
\begin{equation*}
Z_0(\frac{x}{|x|^2})=-Z_0(x),\quad Z_i(\frac{x}{|x|^2})=Z_i(x),\qquad i=1,\dots,n,
\end{equation*}
we get $c_0=0$.

In conclusion, we have $h\equiv0$, contradicting \eqref{max h=1}. The uniqueness up to a dilation follows immediately. This completes the proof of Theorem \ref{thm:rad small ga}.
